export const MATERIAL_CLOSURE_RELEASE = Object.freeze({"version":"material-closure-foundation-v1","checksum":"e42bc9100005e2949ce5c6da5f535a59de8ef307766b532e2ec2f5c568fa866c","manifestSha256":"c1785dd5c1573b542dcd899b1d43bf8f01238762d766251a7b49c8fb3992cb9f","sql":"-- Core schema version material-closure-foundation-v1 (closed build artifact).\n\nSET ROLE backbone_owner;\n\n-- app/knowledge_candidate_inputs.sql\n\n-- Material closure foundation v1. Canonical versioned source; see its closed manifest.\nCREATE TABLE app.knowledge_candidate_inputs (\n  workspace_id uuid NOT NULL REFERENCES app.workspaces (id),\n  candidate_id uuid NOT NULL,\n  format_version integer NOT NULL CHECK (format_version = 1),\n  boundary_seq bigint NOT NULL CHECK (boundary_seq > 0),\n  boundary_hash text NOT NULL CHECK (boundary_hash ~ '^[a-f0-9]{64}$'),\n  capture_seq bigint NOT NULL,\n  capture_hash text NOT NULL CHECK (capture_hash ~ '^[a-f0-9]{64}$'),\n  proposal_seq bigint GENERATED ALWAYS AS (capture_seq + 1) STORED,\n  proposed_by uuid NOT NULL,\n  run_id uuid,\n  run_fence bigint,\n  run_task_id uuid,\n  on_behalf_of uuid,\n  run_tainted_untrusted boolean,\n  run_tainted_sensitive boolean,\n  words_untrusted boolean NOT NULL,\n  kept boolean NOT NULL,\n  claim_digest text NOT NULL CHECK (claim_digest ~ '^[a-f0-9]{64}$'),\n  input_manifest jsonb NOT NULL,\n  input_sha256 text NOT NULL CHECK (input_sha256 ~ '^[a-f0-9]{64}$'),\n  captured_at timestamptz NOT NULL DEFAULT clock_timestamp(),\n  PRIMARY KEY (workspace_id, candidate_id),\n  UNIQUE (workspace_id, proposal_seq),\n  CONSTRAINT candidate_inputs_capture_order CHECK (\n    capture_seq >= boundary_seq AND capture_seq < 9223372036854775807\n  ),\n  CONSTRAINT candidate_inputs_run_snapshot CHECK (\n    (run_id IS NULL AND run_fence IS NULL AND run_task_id IS NULL\n      AND run_tainted_untrusted IS NULL AND run_tainted_sensitive IS NULL)\n    OR (run_id IS NOT NULL AND run_fence IS NOT NULL AND run_fence > 0\n      AND run_task_id IS NOT NULL AND run_tainted_untrusted IS NOT NULL\n      AND run_tainted_sensitive IS NOT NULL)\n  ),\n  CONSTRAINT candidate_inputs_manifest_shape CHECK (\n    jsonb_typeof(input_manifest) IS NOT DISTINCT FROM 'object'\n    AND input_manifest -> 'version' IS NOT DISTINCT FROM '1'::jsonb\n    AND jsonb_typeof(input_manifest -> 'complete') IS NOT DISTINCT FROM 'boolean'\n    AND jsonb_typeof(input_manifest -> 'sources') IS NOT DISTINCT FROM 'array'\n    AND jsonb_typeof(input_manifest -> 'read_edges') IS NOT DISTINCT FROM 'array'\n    AND jsonb_typeof(input_manifest -> 'unknown') IS NOT DISTINCT FROM 'array'\n    AND CASE WHEN input_manifest -> 'complete' = 'true'::jsonb THEN\n      CASE WHEN jsonb_typeof(input_manifest -> 'unknown') = 'array'\n        THEN jsonb_array_length(input_manifest -> 'unknown') = 0 ELSE false END\n      ELSE CASE WHEN jsonb_typeof(input_manifest -> 'unknown') = 'array'\n        THEN jsonb_array_length(input_manifest -> 'unknown') > 0 ELSE false END END\n  ),\n  CONSTRAINT candidate_inputs_candidate_fk FOREIGN KEY (workspace_id, candidate_id)\n    REFERENCES app.knowledge_candidates (workspace_id, id)\n    DEFERRABLE INITIALLY DEFERRED,\n  FOREIGN KEY (workspace_id, boundary_seq) REFERENCES app.ledger (workspace_id, seq),\n  FOREIGN KEY (workspace_id, capture_seq) REFERENCES app.ledger (workspace_id, seq),\n  FOREIGN KEY (workspace_id, proposed_by) REFERENCES app.principals (workspace_id, id),\n  FOREIGN KEY (workspace_id, run_id) REFERENCES app.runs (workspace_id, id),\n  FOREIGN KEY (workspace_id, run_task_id) REFERENCES app.tasks (workspace_id, id),\n  FOREIGN KEY (workspace_id, on_behalf_of) REFERENCES app.principals (workspace_id, id)\n);\nALTER TABLE app.knowledge_candidate_inputs ENABLE ROW LEVEL SECURITY;\nALTER TABLE app.knowledge_candidate_inputs FORCE ROW LEVEL SECURITY;\nCREATE POLICY tenant_wall ON app.knowledge_candidate_inputs AS RESTRICTIVE FOR ALL TO PUBLIC\n  USING (workspace_id = (SELECT sec.current_workspace()))\n  WITH CHECK (workspace_id = (SELECT sec.current_workspace()));\nCREATE POLICY crossings ON app.knowledge_candidate_inputs FOR ALL TO backbone_gov\n  USING (true) WITH CHECK (true);\nCREATE TRIGGER evidence BEFORE UPDATE OR DELETE ON app.knowledge_candidate_inputs\n  FOR EACH ROW EXECUTE FUNCTION sec.t_evidence();\nALTER TABLE app.knowledge_candidate_inputs ENABLE ALWAYS TRIGGER evidence;\nCREATE TRIGGER no_truncate BEFORE TRUNCATE ON app.knowledge_candidate_inputs\n  FOR EACH STATEMENT EXECUTE FUNCTION sec.t_refuse_truncate();\nALTER TABLE app.knowledge_candidate_inputs ENABLE ALWAYS TRIGGER no_truncate;\nREVOKE ALL ON app.knowledge_candidate_inputs FROM PUBLIC, backbone_app, backbone_operator;\nGRANT SELECT, INSERT ON app.knowledge_candidate_inputs TO backbone_gov;\n\n-- app/knowledge_reads.sql\n\n-- Material closure foundation v1. Canonical versioned source; see its closed manifest.\nCREATE TABLE app.knowledge_reads (\n  workspace_id uuid NOT NULL REFERENCES app.workspaces(id),\n  read_id uuid NOT NULL,\n  batch_id uuid NOT NULL,\n  batch_ordinal integer NOT NULL CHECK (batch_ordinal BETWEEN 1 AND 100),\n  read_seq bigint NOT NULL CHECK (read_seq > 0),\n  receiving_run_id uuid NOT NULL,\n  receiving_fence bigint NOT NULL CHECK (receiving_fence > 0),\n  receiving_agent_id uuid NOT NULL,\n  receiving_person_id uuid NOT NULL,\n  receiving_task_id uuid NOT NULL,\n  knowledge_id uuid NOT NULL,\n  candidate_id uuid NOT NULL,\n  source_snapshot jsonb NOT NULL,\n  source_sha256 text NOT NULL CHECK (source_sha256 ~ '^[a-f0-9]{64}$'),\n  source_sensitive boolean NOT NULL,\n  source_elsewhere boolean NOT NULL CHECK (NOT source_elsewhere OR source_sensitive),\n  read_at timestamptz NOT NULL,\n  PRIMARY KEY (workspace_id, read_id),\n  UNIQUE (workspace_id, batch_id, batch_ordinal),\n  UNIQUE (workspace_id, batch_id, knowledge_id),\n  FOREIGN KEY (workspace_id, read_seq) REFERENCES app.ledger(workspace_id, seq),\n  FOREIGN KEY (workspace_id, receiving_run_id) REFERENCES app.runs(workspace_id, id),\n  FOREIGN KEY (workspace_id, receiving_agent_id) REFERENCES app.principals(workspace_id, id),\n  FOREIGN KEY (workspace_id, receiving_person_id) REFERENCES app.principals(workspace_id, id),\n  FOREIGN KEY (workspace_id, receiving_task_id) REFERENCES app.tasks(workspace_id, id),\n  FOREIGN KEY (workspace_id, knowledge_id) REFERENCES app.knowledge(workspace_id, id),\n  FOREIGN KEY (workspace_id, candidate_id) REFERENCES app.knowledge_candidates(workspace_id, id),\n  CONSTRAINT knowledge_read_snapshot CHECK (\n    jsonb_typeof(source_snapshot) IS NOT DISTINCT FROM 'object'\n    AND source_snapshot ->> 'format' IS NOT DISTINCT FROM 'knowledge-personal-closure-v1'\n    AND source_snapshot ->> 'knowledge_id' IS NOT DISTINCT FROM knowledge_id::text\n    AND source_snapshot ->> 'candidate_id' IS NOT DISTINCT FROM candidate_id::text\n    AND source_sha256 = encode(sha256(convert_to(source_snapshot::text, 'UTF8')), 'hex')\n  )\n);\nALTER TABLE app.knowledge_reads OWNER TO backbone_owner;\nALTER TABLE app.knowledge_reads ENABLE ROW LEVEL SECURITY;\nALTER TABLE app.knowledge_reads FORCE ROW LEVEL SECURITY;\nCREATE POLICY tenant_wall ON app.knowledge_reads AS RESTRICTIVE FOR ALL TO PUBLIC\n  USING (workspace_id = (SELECT sec.current_workspace()))\n  WITH CHECK (workspace_id = (SELECT sec.current_workspace()));\nCREATE POLICY crossings ON app.knowledge_reads FOR ALL TO backbone_gov\n  USING (true) WITH CHECK (true);\nCREATE TRIGGER evidence BEFORE UPDATE OR DELETE ON app.knowledge_reads\n  FOR EACH ROW EXECUTE FUNCTION sec.t_evidence();\nALTER TABLE app.knowledge_reads ENABLE ALWAYS TRIGGER evidence;\nCREATE TRIGGER no_truncate BEFORE TRUNCATE ON app.knowledge_reads\n  FOR EACH STATEMENT EXECUTE FUNCTION sec.t_refuse_truncate();\nALTER TABLE app.knowledge_reads ENABLE ALWAYS TRIGGER no_truncate;\nCREATE INDEX knowledge_reads_receiver_cut\n  ON app.knowledge_reads(workspace_id, receiving_run_id, read_seq, read_id);\nREVOKE ALL ON app.knowledge_reads FROM PUBLIC, backbone_app, backbone_operator;\nGRANT SELECT, INSERT ON app.knowledge_reads TO backbone_gov;\n-- No app SELECT or person resolveRead crossing. Gov INSERT is a native code privilege,\n-- not an untrusted writer interface. Source authority is derived by the crossing below.\n\n-- Resource-control prerequisite for the bounded cursor, not an authority shortcut.\nCREATE INDEX knowledge_traced_scan\n  ON app.knowledge(workspace_id,status,created_at,id);\n\nSET ROLE backbone_gov;\n\n-- gov/_material_source_projection.sql\n\n-- Material closure foundation v1. Canonical versioned source; see its closed manifest.\nCREATE FUNCTION gov._material_source_projection(p_episode uuid) RETURNS text\nLANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE\n  ws uuid := sec.current_workspace();\n  system_id uuid := sec.system_principal();\n  e app.episodes%ROWTYPE;\n  b app.material_source_reads%ROWTYPE;\n  observed_by uuid;\n  run_task uuid;\n  current_sensitive boolean;\n  retired bigint;\nBEGIN\n  IF ws IS NULL OR system_id IS NULL OR p_episode IS NULL THEN RETURN 'unknown'; END IF;\n  SELECT source.* INTO e FROM app.episodes source WHERE source.workspace_id = ws AND source.id = p_episode;\n  IF NOT FOUND THEN RETURN 'unknown'; END IF;\n  SELECT reading.* INTO b FROM app.material_source_reads reading\n  WHERE reading.workspace_id = ws AND reading.episode_id = p_episode;\n  IF NOT FOUND THEN RETURN 'unknown'; END IF;\n  SELECT identity.observed_by INTO observed_by FROM app.material_source_identities identity\n  WHERE identity.workspace_id = ws AND identity.material_id = b.material_id AND identity.project_id = b.project_id;\n  IF NOT FOUND OR observed_by IS DISTINCT FROM system_id\n     OR b.recorded_by IS DISTINCT FROM system_id OR e.recorded_by IS DISTINCT FROM system_id\n     OR e.source_kind IS DISTINCT FROM b.source_kind OR e.run_id IS DISTINCT FROM b.run_id\n     OR e.authored_by IS DISTINCT FROM b.authored_by OR e.connection_id IS DISTINCT FROM b.connection_id\n     OR e.content_hash IS DISTINCT FROM b.episode_sha256\n     OR b.episode_sha256 IS DISTINCT FROM encode(sha256(convert_to(e.content, 'UTF8')), 'hex')\n     OR e.document_id IS NOT NULL OR e.document_version IS NOT NULL THEN\n    RETURN 'unknown';\n  END IF;\n  IF b.run_id IS NOT NULL THEN\n    SELECT run.task_id INTO run_task FROM app.runs run WHERE run.workspace_id = ws AND run.id = b.run_id;\n    IF NOT FOUND THEN RETURN 'unknown'; END IF;\n  END IF;\n  IF b.source_kind = 'file' THEN\n    IF e.source_ref IS DISTINCT FROM 'material:' || b.material_id || '@v' || b.material_version::text\n       OR e.task_id IS DISTINCT FROM coalesce(b.requested_task_id, run_task)\n       OR e.trust IS DISTINCT FROM (CASE WHEN b.authored_by IS NULL THEN 'untrusted' ELSE 'trusted' END)\n       OR b.connection_id IS NOT NULL OR b.tool IS NOT NULL THEN\n      RETURN 'unknown';\n    END IF;\n  ELSIF b.source_kind = 'mcp' THEN\n    IF b.run_id IS NULL OR b.connection_id IS NULL OR b.tool IS NULL OR b.requested_task_id IS NOT NULL\n       OR b.authored_by IS NOT NULL OR e.task_id IS DISTINCT FROM run_task OR e.trust IS DISTINCT FROM 'untrusted'\n       OR e.source_ref IS DISTINCT FROM 'mcp:' || b.connection_id::text || '/' || b.tool THEN\n      RETURN 'unknown';\n    END IF;\n    SELECT connection.sensitive INTO current_sensitive FROM app.connections connection\n    WHERE connection.workspace_id = ws AND connection.id = b.connection_id;\n    IF NOT FOUND OR (current_sensitive AND NOT e.sensitive) THEN RETURN 'unknown'; END IF;\n  ELSE\n    RETURN 'unknown';\n  END IF;\n  -- This source version must have one consistent original-byte observation, not competing hashes.\n  IF EXISTS (SELECT FROM app.material_source_reads other\n             WHERE other.workspace_id = ws AND other.material_id = b.material_id\n               AND other.material_version = b.material_version AND other.original_sha256 <> b.original_sha256) THEN\n    RETURN 'unknown';\n  END IF;\n  IF EXISTS (SELECT FROM app.material_source_withdrawals withdrawal\n             WHERE withdrawal.workspace_id = ws AND withdrawal.material_id = b.material_id\n               AND withdrawal.generation >= b.generation) THEN\n    RETURN 'withdrawn';\n  END IF;\n  SELECT count(*) INTO retired FROM app.material_source_withdrawals withdrawal\n  WHERE withdrawal.workspace_id = ws AND withdrawal.material_id = b.material_id;\n  IF retired <> b.generation THEN RETURN 'unknown'; END IF;\n  -- The unique nonnegative tombstones below g, with exactly g rows, prove only Core's prefix.\n  RETURN 'live';\nEND\n$$;\nREVOKE ALL ON FUNCTION gov._material_source_projection(uuid) FROM PUBLIC, backbone_app, backbone_operator;\n\n-- gov/_material_source_state.sql\n\n-- Material closure foundation v1. Canonical versioned source; see its closed manifest.\nCREATE OR REPLACE FUNCTION gov._material_source_state(p_episode uuid) RETURNS text\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog\nAS $$\nDECLARE\n  observed text;\nBEGIN\n  IF current_setting('transaction_isolation') <> 'read committed' THEN\n    RAISE EXCEPTION 'paused: material validation requires READ COMMITTED isolation';\n  END IF;\n  -- Preserve the old unknown result for an absent workspace/system/episode identity.\n  -- The projection repeats these identity checks in the later authoritative statement.\n  IF sec.current_workspace() IS NULL OR sec.system_principal() IS NULL OR p_episode IS NULL THEN\n    RETURN 'unknown';\n  END IF;\n  PERFORM gov._lock_workspace();\n  -- A separate SELECT after the lock: never a STABLE projection in the waiting statement.\n  SELECT gov._material_source_projection(p_episode) INTO observed;\n  RETURN observed;\nEND\n$$;\nREVOKE ALL ON FUNCTION gov._material_source_state(uuid) FROM PUBLIC, backbone_app, backbone_operator;\n\n-- gov/_create_workspace.sql\n\n-- Material closure foundation v1. Canonical versioned source; see its closed manifest.\nCREATE OR REPLACE FUNCTION gov._create_workspace(p_name text, p_kind text, p_owner_name text, p_owner_email text)\nRETURNS TABLE (workspace_id uuid, owner_id uuid, system_id uuid)\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE\n  ws uuid := gen_random_uuid();\n  owner uuid := gen_random_uuid();\n  sys uuid := gen_random_uuid();\nBEGIN\n  IF current_setting('transaction_isolation') <> 'read committed' THEN\n    RAISE EXCEPTION 'paused: workspace initialization requires READ COMMITTED isolation';\n  END IF;\n  -- Both public wrappers already hold this mutex; reentry is the same transaction.\n  -- An absent installation row is unknown, never permission to create an unmarked workspace.\n  PERFORM 1 FROM ops.installation WHERE singleton FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'paused: installation state could not be verified'; END IF;\n  IF p_kind IS NULL OR p_kind NOT IN ('personal', 'team', 'company') THEN\n    RAISE EXCEPTION 'invalid: a workspace is personal, team or company';\n  END IF;\n  IF p_name IS NULL OR length(p_name) NOT BETWEEN 1 AND 200 THEN\n    RAISE EXCEPTION 'invalid: a workspace needs a name';\n  END IF;\n  PERFORM set_config('backbone.workspace', ws::text, true);\n  PERFORM set_config('backbone.principal', '', true);\n  PERFORM set_config('backbone.run', '', true);\n  PERFORM set_config('backbone.secret', '', true);\n  INSERT INTO app.workspaces (id, name, kind) VALUES (ws, p_name, p_kind);\n  INSERT INTO app.ledger_heads (workspace_id) VALUES (ws);\n  INSERT INTO ops.workspace_keys (workspace_id, digest_key) VALUES (ws, crypto.gen_random_bytes(32));\n  INSERT INTO app.principals (workspace_id, id, kind, role, name, email) VALUES (ws, owner, 'person', 'owner', p_owner_name, p_owner_email);\n  INSERT INTO app.principals (workspace_id, id, kind, name) VALUES (ws, sys, 'system', 'System');\n  PERFORM gov._append('workspace.created', ws::text, jsonb_build_object('kind', p_kind, 'owner', owner, 'system', sys), owner);\n  PERFORM gov._append('knowledge.dependencies_enabled', NULL, jsonb_build_object('version', 'material-closure-foundation-v1'));\n  RETURN QUERY SELECT ws, owner, sys;\nEND\n$$;\nREVOKE ALL ON FUNCTION gov._create_workspace(text,text,text,text) FROM PUBLIC, backbone_app, backbone_operator;\n\n-- gov/_candidate_claim_digest_v1.sql\n\n-- Material closure foundation v1. Canonical versioned source; see its closed manifest.\nCREATE FUNCTION gov._candidate_claim_digest_v1(p_claim app.knowledge_candidates) RETURNS text\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog\nAS $$\n  SELECT sec.digest(jsonb_build_object(\n    'version', 1,\n    'workspace', (p_claim).workspace_id,\n    'candidate', (p_claim).id,\n    'statement', (p_claim).statement,\n    'topic', (p_claim).topic,\n    'evidence', (p_claim).evidence,\n    'proposed_by', (p_claim).proposed_by,\n    'run', (p_claim).run_id,\n    'on_behalf_of', (p_claim).on_behalf_of,\n    'words_untrusted', (p_claim).words_untrusted,\n    'kept', (p_claim).kept,\n    'created_at', to_char((p_claim).created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD\"T\"HH24:MI:SS.US\"Z\"')\n  )::text)\n  WHERE (p_claim).workspace_id = sec.current_workspace()\n$$;\nREVOKE ALL ON FUNCTION gov._candidate_claim_digest_v1(app.knowledge_candidates)\n  FROM PUBLIC, backbone_app, backbone_operator;\n\n-- gov/_personal_message_inputs_v1.sql\n\n-- Material closure foundation v1. Canonical versioned source; see its closed manifest.\nCREATE FUNCTION gov._personal_message_inputs_v1(p_claim app.knowledge_candidates, p_receiving_person uuid, p_capture_seq bigint)\nRETURNS jsonb\nLANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE\n  ws uuid := sec.current_workspace();\n  unavailable jsonb := jsonb_build_object('format', 'personal-message-inputs-v1', 'state', 'unknown');\n  c app.knowledge_candidates%ROWTYPE;\n  e app.episodes%ROWTYPE;\n  m app.messages%ROWTYPE;\n  task app.tasks%ROWTYPE;\n  recording app.ledger%ROWTYPE;\n  posting app.ledger%ROWTYPE;\n  citation jsonb;\n  roots jsonb := '[]'::jsonb;\n  seen uuid[] := ARRAY[]::uuid[];\n  episode_id uuid;\n  message_id uuid;\n  system_id uuid;\n  matches bigint;\n  ref_digest text;\n  content_digest text;\n  content_sha256 text;\n  excerpt text;\n  claim_digest text;\nBEGIN\n  IF ws IS NULL OR (p_claim).workspace_id IS DISTINCT FROM ws OR (p_claim).id IS NULL\n     OR p_receiving_person IS NULL OR p_capture_seq IS NULL OR p_capture_seq < 1 THEN\n    RETURN unavailable || jsonb_build_object('reason', 'missing_native_identity');\n  END IF;\n  IF NOT EXISTS (\n    SELECT FROM app.principals p\n    WHERE p.workspace_id = ws AND p.id = p_receiving_person\n      AND p.kind = 'person' AND p.status = 'active'\n  ) THEN\n    RETURN unavailable || jsonb_build_object('reason', 'invalid_receiving_person');\n  END IF;\n\n  c := p_claim;\n  -- Pre-proposal claim: no candidate/status/proposal lookup is allowed here.\n  IF c.run_id IS NOT NULL THEN\n    RETURN unavailable || jsonb_build_object('reason', 'run_lineage_not_demonstrated');\n  END IF;\n  IF c.on_behalf_of IS DISTINCT FROM c.proposed_by\n     OR c.words_untrusted OR c.kept OR NOT EXISTS (\n       SELECT FROM app.principals p WHERE p.workspace_id = ws AND p.id = c.proposed_by AND p.kind = 'person' AND p.status = 'active'\n     ) THEN\n    RETURN unavailable || jsonb_build_object('reason', 'not_a_personal_declaration');\n  END IF;\n\n  IF jsonb_typeof(c.evidence) IS DISTINCT FROM 'array' THEN\n    RETURN unavailable || jsonb_build_object('reason', 'unsupported_citation_shape');\n  END IF;\n  -- Operational refusal, never a truncated proof. The final implementation must measure\n  -- this bounded family; larger candidates stay UNKNOWN until deliberately supported.\n  IF jsonb_array_length(c.evidence) NOT BETWEEN 1 AND 64 THEN\n    RETURN unavailable || jsonb_build_object('reason', 'unsupported_citation_count');\n  END IF;\n  system_id := sec.system_principal();\n  IF system_id IS NULL THEN\n    RETURN unavailable || jsonb_build_object('reason', 'missing_system_recorder');\n  END IF;\n\n  FOR citation IN SELECT value FROM jsonb_array_elements(c.evidence) LOOP\n    IF jsonb_typeof(citation) IS DISTINCT FROM 'object' THEN\n      RETURN unavailable || jsonb_build_object('reason', 'unsupported_citation_shape');\n    END IF;\n    IF jsonb_typeof(citation -> 'episode') IS DISTINCT FROM 'string'\n       OR jsonb_typeof(citation -> 'excerpt') IS DISTINCT FROM 'string'\n       OR (SELECT count(*) FROM jsonb_object_keys(citation)) <> 2\n       OR citation ->> 'episode' !~ '^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$' THEN\n      RETURN unavailable || jsonb_build_object('reason', 'unsupported_citation_shape');\n    END IF;\n    episode_id := (citation ->> 'episode')::uuid;\n    IF episode_id = ANY(seen) THEN\n      RETURN unavailable || jsonb_build_object('reason', 'duplicate_citation_identity');\n    END IF;\n    seen := array_append(seen, episode_id);\n    SELECT * INTO e FROM app.episodes x WHERE x.workspace_id = ws AND x.id = episode_id;\n    IF NOT FOUND THEN\n      RETURN unavailable || jsonb_build_object('reason', 'missing_citation_episode');\n    END IF;\n    IF e.source_kind IS DISTINCT FROM 'message' OR e.run_id IS NOT NULL\n       OR e.authored_by IS NULL OR e.authored_by = c.proposed_by\n       OR e.recorded_by IS DISTINCT FROM system_id OR e.trust IS DISTINCT FROM 'trusted'\n       OR e.task_id IS NULL OR e.document_id IS NOT NULL OR e.document_version IS NOT NULL\n       OR e.connection_id IS NOT NULL THEN\n      RETURN unavailable || jsonb_build_object('reason', 'not_a_standalone_person_message_source');\n    END IF;\n    IF e.source_ref !~ '^message:[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$' THEN\n      RETURN unavailable || jsonb_build_object('reason', 'missing_native_message_reference');\n    END IF;\n    -- The reference is only a lookup hint. Authority comes from the native message,\n    -- author/role/content/task match and its independent immutable posting event.\n    message_id := substring(e.source_ref FROM 9)::uuid;\n    SELECT * INTO m FROM app.messages x WHERE x.workspace_id = ws AND x.id = message_id;\n    IF NOT FOUND THEN\n      RETURN unavailable || jsonb_build_object('reason', 'missing_native_message');\n    END IF;\n    IF m.role IS DISTINCT FROM 'person' OR m.run_id IS NOT NULL OR m.only_for IS NOT NULL\n       OR m.author_id IS DISTINCT FROM e.authored_by OR m.task_id IS DISTINCT FROM e.task_id\n       OR m.content IS DISTINCT FROM e.content OR NOT EXISTS (\n         SELECT FROM app.principals p WHERE p.workspace_id = ws AND p.id = m.author_id AND p.kind = 'person'\n       ) THEN\n      RETURN unavailable || jsonb_build_object('reason', 'native_message_row_mismatch');\n    END IF;\n    excerpt := citation ->> 'excerpt';\n    content_sha256 := encode(sha256(convert_to(e.content, 'UTF8')), 'hex');\n    IF e.content_hash IS DISTINCT FROM content_sha256 OR length(excerpt) = 0\n       OR position(excerpt IN e.content) = 0 THEN\n      RETURN unavailable || jsonb_build_object('reason', 'citation_content_mismatch');\n    END IF;\n\n    SELECT count(*) INTO matches FROM app.ledger l\n    WHERE l.workspace_id = ws AND l.entry_type = 'message.posted' AND l.subject = m.id::text;\n    IF matches <> 1 THEN\n      RETURN unavailable || jsonb_build_object('reason', 'ambiguous_message_posting_cut');\n    END IF;\n    SELECT * INTO posting FROM app.ledger l\n    WHERE l.workspace_id = ws AND l.entry_type = 'message.posted' AND l.subject = m.id::text;\n    IF posting.actor_id IS DISTINCT FROM m.author_id\n       OR posting.payload IS DISTINCT FROM jsonb_build_object('task', m.task_id, 'role', 'person') THEN\n      RETURN unavailable || jsonb_build_object('reason', 'message_posting_row_mismatch');\n    END IF;\n    IF posting.hash IS DISTINCT FROM sec.ledger_hash(posting.prev_hash, posting.workspace_id,\n         posting.seq, posting.entry_type, posting.actor_id, posting.subject, posting.payload, posting.at)\n       OR NOT EXISTS (\n         SELECT FROM app.ledger previous WHERE previous.workspace_id = ws\n           AND previous.seq = posting.seq - 1 AND previous.hash = posting.prev_hash\n       ) THEN\n      RETURN unavailable || jsonb_build_object('reason', 'message_posting_chain_mismatch');\n    END IF;\n\n    SELECT count(*) INTO matches FROM app.ledger l\n    WHERE l.workspace_id = ws AND l.entry_type = 'source.recorded' AND l.subject = e.id::text;\n    IF matches <> 1 THEN\n      RETURN unavailable || jsonb_build_object('reason', 'ambiguous_source_cut');\n    END IF;\n    SELECT * INTO recording FROM app.ledger l\n    WHERE l.workspace_id = ws AND l.entry_type = 'source.recorded' AND l.subject = e.id::text;\n    ref_digest := sec.digest(e.source_ref);\n    content_digest := sec.digest(e.content);\n    IF ref_digest IS NULL OR ref_digest !~ '^[a-f0-9]{64}$'\n       OR content_digest IS NULL OR content_digest !~ '^[a-f0-9]{64}$'\n       OR recording.actor_id IS DISTINCT FROM system_id\n       OR recording.payload IS DISTINCT FROM jsonb_build_object(\n         'kind', 'message', 'trust', 'trusted', 'run', NULL, 'task', e.task_id,\n         'ref', ref_digest, 'content', content_digest)\n       OR NOT (posting.seq < recording.seq AND recording.seq <= p_capture_seq) THEN\n      RETURN unavailable || jsonb_build_object('reason', 'source_recording_row_or_order_mismatch');\n    END IF;\n    IF recording.hash IS DISTINCT FROM sec.ledger_hash(recording.prev_hash, recording.workspace_id,\n         recording.seq, recording.entry_type, recording.actor_id, recording.subject, recording.payload, recording.at)\n       OR NOT EXISTS (\n         SELECT FROM app.ledger previous WHERE previous.workspace_id = ws\n           AND previous.seq = recording.seq - 1 AND previous.hash = recording.prev_hash\n       ) THEN\n      RETURN unavailable || jsonb_build_object('reason', 'source_recording_chain_mismatch');\n    END IF;\n\n    SELECT * INTO task FROM app.tasks x WHERE x.workspace_id = ws AND x.id = e.task_id;\n    IF NOT FOUND OR NOT sec.task_visible_to(e.task_id, p_receiving_person) THEN\n      RETURN unavailable || jsonb_build_object('reason', 'receiving_audience_unavailable');\n    END IF;\n    roots := roots || jsonb_build_array(jsonb_build_object(\n      'episode_id', e.id, 'message_id', m.id, 'author_id', m.author_id, 'task_id', m.task_id,\n      'message_seq', posting.seq::text, 'source_seq', recording.seq::text,\n      'source_kind', 'message', 'content_sha256', content_sha256,\n      'excerpt_sha256', encode(sha256(convert_to(excerpt, 'UTF8')), 'hex'),\n      'recorded_sensitive', e.sensitive\n    ));\n  END LOOP;\n\n  -- One shared keyed encoder binds this result to the sibling immutable candidate proof.\n  -- Its complete definition depends only on the existing candidate row and workspace key,\n  -- not the unfinished proof table or BEFORE guard. Install it before this helper.\n  claim_digest := gov._candidate_claim_digest_v1(c);\n  IF claim_digest IS NULL OR claim_digest !~ '^[a-f0-9]{64}$' THEN\n    RETURN unavailable || jsonb_build_object('reason', 'candidate_claim_digest_unavailable');\n  END IF;\n  RETURN jsonb_build_object(\n    'format', 'personal-message-inputs-v1', 'state', 'known_personal_inputs',\n    'trust_boundary', 'explicit_native_personal_declaration',\n    'workspace_id', ws, 'candidate_id', c.id, 'proposed_by', c.proposed_by,\n    'capture_seq', p_capture_seq::text,\n    'claim_digest', claim_digest,\n    'roots', (SELECT jsonb_agg(r.value ORDER BY (r.value ->> 'episode_id') COLLATE \"C\")\n      FROM jsonb_array_elements(roots) r(value))\n  );\nEND\n$$;\nALTER FUNCTION gov._personal_message_inputs_v1(app.knowledge_candidates,uuid,bigint) OWNER TO backbone_gov;\nREVOKE ALL ON FUNCTION gov._personal_message_inputs_v1(app.knowledge_candidates,uuid,bigint) FROM PUBLIC, backbone_app, backbone_operator;\n-- The owner executes it internally; there is no direct app/operator or caller completeness grant.\n\n-- gov/_personal_message_roots_v1.sql\n\n-- Material closure foundation v1. Canonical versioned source; see its closed manifest.\nCREATE FUNCTION gov._personal_message_roots_v1(p_candidate uuid, p_receiving_person uuid)\nRETURNS jsonb\nLANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE\n  ws uuid := sec.current_workspace();\n  unavailable jsonb := jsonb_build_object('format', 'personal-message-roots-v1', 'state', 'unknown');\n  c app.knowledge_candidates%ROWTYPE;\n  e app.episodes%ROWTYPE;\n  m app.messages%ROWTYPE;\n  task app.tasks%ROWTYPE;\n  proposal app.ledger%ROWTYPE;\n  recording app.ledger%ROWTYPE;\n  posting app.ledger%ROWTYPE;\n  citation jsonb;\n  roots jsonb := '[]'::jsonb;\n  seen uuid[] := ARRAY[]::uuid[];\n  episode_id uuid;\n  message_id uuid;\n  system_id uuid;\n  matches bigint;\n  topic_digest text;\n  ref_digest text;\n  content_digest text;\n  content_sha256 text;\n  excerpt text;\n  claim_digest text;\nBEGIN\n  IF ws IS NULL OR p_candidate IS NULL OR p_receiving_person IS NULL THEN\n    RETURN unavailable || jsonb_build_object('reason', 'missing_native_identity');\n  END IF;\n  IF NOT EXISTS (\n    SELECT FROM app.principals p\n    WHERE p.workspace_id = ws AND p.id = p_receiving_person\n      AND p.kind = 'person' AND p.status = 'active'\n  ) THEN\n    RETURN unavailable || jsonb_build_object('reason', 'invalid_receiving_person');\n  END IF;\n\n  SELECT * INTO c FROM app.knowledge_candidates x WHERE x.workspace_id = ws AND x.id = p_candidate;\n  IF NOT FOUND THEN\n    RETURN unavailable || jsonb_build_object('reason', 'missing_candidate');\n  END IF;\n  -- This is a narrow accepted-knowledge input family, not a creation-time predicate.\n  -- A NULL run is necessary but never sufficient. Native personal identity, its real event\n  -- and the exact authored roots below supply the positive declaration boundary.\n  IF c.run_id IS NOT NULL THEN\n    RETURN unavailable || jsonb_build_object('reason', 'run_lineage_not_demonstrated');\n  END IF;\n  IF c.status IS DISTINCT FROM 'accepted' OR c.on_behalf_of IS DISTINCT FROM c.proposed_by\n     OR c.words_untrusted OR c.kept OR NOT EXISTS (\n       SELECT FROM app.principals p WHERE p.workspace_id = ws AND p.id = c.proposed_by AND p.kind = 'person'\n     ) THEN\n    RETURN unavailable || jsonb_build_object('reason', 'not_a_personal_declaration');\n  END IF;\n\n  SELECT count(*) INTO matches FROM app.ledger l\n  WHERE l.workspace_id = ws AND l.entry_type = 'knowledge.proposed' AND l.subject = c.id::text;\n  IF matches <> 1 THEN\n    RETURN unavailable || jsonb_build_object('reason', 'ambiguous_proposal_cut');\n  END IF;\n  SELECT * INTO proposal FROM app.ledger l\n  WHERE l.workspace_id = ws AND l.entry_type = 'knowledge.proposed' AND l.subject = c.id::text;\n  topic_digest := sec.digest(c.topic);\n  IF topic_digest IS NULL OR topic_digest !~ '^[a-f0-9]{64}$'\n     OR proposal.actor_id IS DISTINCT FROM c.proposed_by\n     OR NOT (\n       proposal.payload = jsonb_build_object('run', NULL, 'topic', topic_digest)\n       -- Released propose_candidate digests raw p_topic but coalesces its row to general.\n       OR (c.topic = 'general' AND proposal.payload = jsonb_build_object('run', NULL, 'topic', NULL))\n     ) THEN\n    RETURN unavailable || jsonb_build_object('reason', 'proposal_row_mismatch');\n  END IF;\n  IF proposal.hash IS DISTINCT FROM sec.ledger_hash(proposal.prev_hash, proposal.workspace_id,\n       proposal.seq, proposal.entry_type, proposal.actor_id, proposal.subject, proposal.payload, proposal.at)\n     OR NOT EXISTS (\n       SELECT FROM app.ledger previous WHERE previous.workspace_id = ws\n         AND previous.seq = proposal.seq - 1 AND previous.hash = proposal.prev_hash\n     ) THEN\n    RETURN unavailable || jsonb_build_object('reason', 'proposal_chain_mismatch');\n  END IF;\n\n  IF jsonb_typeof(c.evidence) IS DISTINCT FROM 'array' THEN\n    RETURN unavailable || jsonb_build_object('reason', 'unsupported_citation_shape');\n  END IF;\n  -- Operational refusal, never a truncated proof. The final implementation must measure\n  -- this bounded family; larger candidates stay UNKNOWN until deliberately supported.\n  IF jsonb_array_length(c.evidence) NOT BETWEEN 1 AND 64 THEN\n    RETURN unavailable || jsonb_build_object('reason', 'unsupported_citation_count');\n  END IF;\n  system_id := sec.system_principal();\n  IF system_id IS NULL THEN\n    RETURN unavailable || jsonb_build_object('reason', 'missing_system_recorder');\n  END IF;\n\n  FOR citation IN SELECT value FROM jsonb_array_elements(c.evidence) LOOP\n    IF jsonb_typeof(citation) IS DISTINCT FROM 'object' THEN\n      RETURN unavailable || jsonb_build_object('reason', 'unsupported_citation_shape');\n    END IF;\n    IF jsonb_typeof(citation -> 'episode') IS DISTINCT FROM 'string'\n       OR jsonb_typeof(citation -> 'excerpt') IS DISTINCT FROM 'string'\n       OR (SELECT count(*) FROM jsonb_object_keys(citation)) <> 2\n       OR citation ->> 'episode' !~ '^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$' THEN\n      RETURN unavailable || jsonb_build_object('reason', 'unsupported_citation_shape');\n    END IF;\n    episode_id := (citation ->> 'episode')::uuid;\n    IF episode_id = ANY(seen) THEN\n      RETURN unavailable || jsonb_build_object('reason', 'duplicate_citation_identity');\n    END IF;\n    seen := array_append(seen, episode_id);\n    SELECT * INTO e FROM app.episodes x WHERE x.workspace_id = ws AND x.id = episode_id;\n    IF NOT FOUND THEN\n      RETURN unavailable || jsonb_build_object('reason', 'missing_citation_episode');\n    END IF;\n    IF e.source_kind IS DISTINCT FROM 'message' OR e.run_id IS NOT NULL\n       OR e.authored_by IS NULL OR e.authored_by = c.proposed_by\n       OR e.recorded_by IS DISTINCT FROM system_id OR e.trust IS DISTINCT FROM 'trusted'\n       OR e.task_id IS NULL OR e.document_id IS NOT NULL OR e.document_version IS NOT NULL\n       OR e.connection_id IS NOT NULL THEN\n      RETURN unavailable || jsonb_build_object('reason', 'not_a_standalone_person_message_source');\n    END IF;\n    IF e.source_ref !~ '^message:[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$' THEN\n      RETURN unavailable || jsonb_build_object('reason', 'missing_native_message_reference');\n    END IF;\n    -- The reference is only a lookup hint. Authority comes from the native message,\n    -- author/role/content/task match and its independent immutable posting event.\n    message_id := substring(e.source_ref FROM 9)::uuid;\n    SELECT * INTO m FROM app.messages x WHERE x.workspace_id = ws AND x.id = message_id;\n    IF NOT FOUND THEN\n      RETURN unavailable || jsonb_build_object('reason', 'missing_native_message');\n    END IF;\n    IF m.role IS DISTINCT FROM 'person' OR m.run_id IS NOT NULL OR m.only_for IS NOT NULL\n       OR m.author_id IS DISTINCT FROM e.authored_by OR m.task_id IS DISTINCT FROM e.task_id\n       OR m.content IS DISTINCT FROM e.content OR NOT EXISTS (\n         SELECT FROM app.principals p WHERE p.workspace_id = ws AND p.id = m.author_id AND p.kind = 'person'\n       ) THEN\n      RETURN unavailable || jsonb_build_object('reason', 'native_message_row_mismatch');\n    END IF;\n    excerpt := citation ->> 'excerpt';\n    content_sha256 := encode(sha256(convert_to(e.content, 'UTF8')), 'hex');\n    IF e.content_hash IS DISTINCT FROM content_sha256 OR length(excerpt) = 0\n       OR position(excerpt IN e.content) = 0 THEN\n      RETURN unavailable || jsonb_build_object('reason', 'citation_content_mismatch');\n    END IF;\n\n    SELECT count(*) INTO matches FROM app.ledger l\n    WHERE l.workspace_id = ws AND l.entry_type = 'message.posted' AND l.subject = m.id::text;\n    IF matches <> 1 THEN\n      RETURN unavailable || jsonb_build_object('reason', 'ambiguous_message_posting_cut');\n    END IF;\n    SELECT * INTO posting FROM app.ledger l\n    WHERE l.workspace_id = ws AND l.entry_type = 'message.posted' AND l.subject = m.id::text;\n    IF posting.actor_id IS DISTINCT FROM m.author_id\n       OR posting.payload IS DISTINCT FROM jsonb_build_object('task', m.task_id, 'role', 'person') THEN\n      RETURN unavailable || jsonb_build_object('reason', 'message_posting_row_mismatch');\n    END IF;\n    IF posting.hash IS DISTINCT FROM sec.ledger_hash(posting.prev_hash, posting.workspace_id,\n         posting.seq, posting.entry_type, posting.actor_id, posting.subject, posting.payload, posting.at)\n       OR NOT EXISTS (\n         SELECT FROM app.ledger previous WHERE previous.workspace_id = ws\n           AND previous.seq = posting.seq - 1 AND previous.hash = posting.prev_hash\n       ) THEN\n      RETURN unavailable || jsonb_build_object('reason', 'message_posting_chain_mismatch');\n    END IF;\n\n    SELECT count(*) INTO matches FROM app.ledger l\n    WHERE l.workspace_id = ws AND l.entry_type = 'source.recorded' AND l.subject = e.id::text;\n    IF matches <> 1 THEN\n      RETURN unavailable || jsonb_build_object('reason', 'ambiguous_source_cut');\n    END IF;\n    SELECT * INTO recording FROM app.ledger l\n    WHERE l.workspace_id = ws AND l.entry_type = 'source.recorded' AND l.subject = e.id::text;\n    ref_digest := sec.digest(e.source_ref);\n    content_digest := sec.digest(e.content);\n    IF ref_digest IS NULL OR ref_digest !~ '^[a-f0-9]{64}$'\n       OR content_digest IS NULL OR content_digest !~ '^[a-f0-9]{64}$'\n       OR recording.actor_id IS DISTINCT FROM system_id\n       OR recording.payload IS DISTINCT FROM jsonb_build_object(\n         'kind', 'message', 'trust', 'trusted', 'run', NULL, 'task', e.task_id,\n         'ref', ref_digest, 'content', content_digest)\n       OR NOT (posting.seq < recording.seq AND recording.seq < proposal.seq) THEN\n      RETURN unavailable || jsonb_build_object('reason', 'source_recording_row_or_order_mismatch');\n    END IF;\n    IF recording.hash IS DISTINCT FROM sec.ledger_hash(recording.prev_hash, recording.workspace_id,\n         recording.seq, recording.entry_type, recording.actor_id, recording.subject, recording.payload, recording.at)\n       OR NOT EXISTS (\n         SELECT FROM app.ledger previous WHERE previous.workspace_id = ws\n           AND previous.seq = recording.seq - 1 AND previous.hash = recording.prev_hash\n       ) THEN\n      RETURN unavailable || jsonb_build_object('reason', 'source_recording_chain_mismatch');\n    END IF;\n\n    SELECT * INTO task FROM app.tasks x WHERE x.workspace_id = ws AND x.id = e.task_id;\n    IF NOT FOUND OR NOT sec.task_visible_to(e.task_id, p_receiving_person) THEN\n      RETURN unavailable || jsonb_build_object('reason', 'receiving_audience_unavailable');\n    END IF;\n    roots := roots || jsonb_build_array(jsonb_build_object(\n      'episode_id', e.id, 'message_id', m.id, 'author_id', m.author_id, 'task_id', m.task_id,\n      'message_seq', posting.seq::text, 'source_seq', recording.seq::text,\n      'source_kind', 'message', 'content_sha256', content_sha256,\n      'excerpt_sha256', encode(sha256(convert_to(excerpt, 'UTF8')), 'hex'),\n      'recorded_sensitive', e.sensitive, 'currently_sensitive', e.sensitive OR task.visibility = 'private'\n    ));\n  END LOOP;\n\n  -- One shared keyed encoder binds this result to the sibling immutable candidate proof.\n  -- Its complete definition depends only on the existing candidate row and workspace key,\n  -- not the unfinished proof table or BEFORE guard. Install it before this helper.\n  claim_digest := gov._candidate_claim_digest_v1(c);\n  IF claim_digest IS NULL OR claim_digest !~ '^[a-f0-9]{64}$' THEN\n    RETURN unavailable || jsonb_build_object('reason', 'candidate_claim_digest_unavailable');\n  END IF;\n  RETURN jsonb_build_object(\n    'format', 'personal-message-roots-v1', 'state', 'known_personal_roots',\n    'trust_boundary', 'explicit_native_personal_declaration',\n    'workspace_id', ws, 'candidate_id', c.id, 'proposed_by', c.proposed_by,\n    'receiving_person', p_receiving_person, 'proposal_seq', proposal.seq::text,\n    'claim_digest', claim_digest,\n    'roots', roots\n  );\nEND\n$$;\nALTER FUNCTION gov._personal_message_roots_v1(uuid,uuid) OWNER TO backbone_gov;\nREVOKE ALL ON FUNCTION gov._personal_message_roots_v1(uuid,uuid) FROM PUBLIC, backbone_app, backbone_operator;\n-- The owner executes it internally; there is no direct app/operator or caller completeness grant.\n\n-- gov/_candidate_input_manifest_v1.sql\n\n-- Material closure foundation v1. Canonical versioned source; see its closed manifest.\nCREATE FUNCTION gov._candidate_input_manifest_v1(p_claim app.knowledge_candidates, p_capture_seq bigint)\nRETURNS jsonb\nLANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE\n  ws uuid := sec.current_workspace();\n  personal jsonb;\n  sources jsonb := '[]'::jsonb;\n  edges jsonb := '[]'::jsonb;\n  unknowns jsonb := '[]'::jsonb;\n  e app.episodes%ROWTYPE;\n  receipt app.material_source_reads%ROWTYPE;\n  l app.ledger%ROWTYPE;\n  k app.knowledge_reads%ROWTYPE;\n  native_run app.runs%ROWTYPE;\n  recordings jsonb;\n  registrations jsonb;\n  citations jsonb;\n  n bigint;\n  material_state text;\n  reserved boolean;\nBEGIN\n  IF ws IS NULL OR (p_claim).workspace_id IS DISTINCT FROM ws OR p_capture_seq IS NULL OR p_capture_seq < 1 THEN\n    RAISE EXCEPTION 'paused: input snapshot requires native workspace and ledger cut';\n  END IF;\n  personal := gov._personal_message_inputs_v1(p_claim, (p_claim).proposed_by, p_capture_seq);\n  IF personal ->> 'state' = 'known_personal_inputs' THEN\n    RETURN jsonb_build_object('version', 1, 'complete', true, 'sources', personal -> 'roots',\n      'read_edges', '[]'::jsonb, 'unknown', '[]'::jsonb);\n  END IF;\n  unknowns := unknowns || jsonb_build_array(jsonb_build_object(\n    'kind', CASE WHEN (p_claim).run_id IS NULL THEN 'unsupported_standalone_declaration'\n      ELSE 'untraced_native_producers' END,\n    'personal_family_reason', personal ->> 'reason', 'run_id', (p_claim).run_id));\n\n  -- No caller-supplied subset: every extant episode assigned to the native run plus\n  -- every citation, even when its historical recording is absent/ambiguous, is retained.\n  FOR e IN SELECT x.* FROM app.episodes x WHERE x.workspace_id = ws AND (\n    ((p_claim).run_id IS NOT NULL AND x.run_id = (p_claim).run_id\n      AND NOT ((SELECT count(*) FROM app.ledger cut WHERE cut.workspace_id=ws\n        AND cut.entry_type='source.recorded' AND cut.subject=x.id::text)=1\n        AND EXISTS (SELECT FROM app.ledger cut WHERE cut.workspace_id=ws\n          AND cut.entry_type='source.recorded' AND cut.subject=x.id::text AND cut.seq>p_capture_seq)))\n    OR EXISTS (SELECT FROM jsonb_array_elements((p_claim).evidence) c\n      WHERE c ->> 'episode' = x.id::text)) ORDER BY x.id LOOP\n    SELECT coalesce(jsonb_agg(jsonb_build_object('ordinal', c.ordinality::text,\n      'excerpt_sha256', encode(sha256(convert_to(c.value ->> 'excerpt', 'UTF8')), 'hex'),\n      'verbatim', length(c.value ->> 'excerpt') > 0 AND position((c.value ->> 'excerpt') IN e.content) > 0)\n      ORDER BY c.ordinality), '[]'::jsonb) INTO citations\n    FROM jsonb_array_elements((p_claim).evidence) WITH ORDINALITY c(value, ordinality)\n    WHERE c.value ->> 'episode' = e.id::text;\n    IF EXISTS (SELECT FROM jsonb_array_elements(citations) c WHERE c ->> 'verbatim' IS DISTINCT FROM 'true') THEN\n      unknowns := unknowns || jsonb_build_array(jsonb_build_object('kind','citation_not_verbatim','episode_id',e.id));\n    END IF;\n    SELECT count(*), coalesce(jsonb_agg(jsonb_build_object(\n      'seq', x.seq::text, 'actor_id', x.actor_id, 'payload', x.payload,\n      'prev_hash', x.prev_hash, 'hash', x.hash) ORDER BY x.seq), '[]'::jsonb)\n    INTO n, recordings FROM app.ledger x WHERE x.workspace_id = ws\n      AND x.entry_type = 'source.recorded' AND x.subject = e.id::text AND x.seq <= p_capture_seq;\n    IF n <> 1 OR e.content_hash IS DISTINCT FROM encode(sha256(convert_to(e.content, 'UTF8')), 'hex')\n       OR EXISTS (SELECT FROM app.ledger x WHERE x.workspace_id = ws AND x.entry_type = 'source.recorded'\n         AND x.subject = e.id::text AND (x.seq > p_capture_seq\n          OR x.actor_id IS DISTINCT FROM sec.system_principal()\n          OR x.payload IS DISTINCT FROM (CASE\n            WHEN e.source_kind IN ('file','sandbox','message','web') THEN jsonb_build_object(\n              'kind',e.source_kind,'trust',e.trust,'run',e.run_id,'task',e.task_id,\n              'ref',sec.digest(e.source_ref),'content',sec.digest(e.content))\n            WHEN e.source_kind='document' THEN jsonb_build_object('kind','document','run',e.run_id,\n              'document',e.document_id,'version',e.document_version)\n            WHEN e.source_kind='mcp' THEN jsonb_build_object('kind','mcp','run',e.run_id,\n              'connection',e.connection_id,'tool',sec.digest(substring(e.source_ref FROM 42)))\n            ELSE NULL::jsonb END)\n          OR x.hash IS DISTINCT FROM sec.ledger_hash(x.prev_hash,x.workspace_id,x.seq,x.entry_type,x.actor_id,x.subject,x.payload,x.at)\n          OR NOT EXISTS (SELECT FROM app.ledger prev WHERE prev.workspace_id=ws\n            AND prev.seq=x.seq-1 AND prev.hash=x.prev_hash))) THEN\n      unknowns := unknowns || jsonb_build_array(jsonb_build_object('kind','source_history_not_demonstrated','episode_id',e.id));\n    END IF;\n    IF e.task_id IS NOT NULL AND NOT (\n      ((p_claim).on_behalf_of IS NOT NULL AND sec.task_visible_to(e.task_id,(p_claim).on_behalf_of))\n      OR ((p_claim).on_behalf_of IS NULL AND EXISTS (SELECT FROM app.tasks t WHERE t.workspace_id=ws\n        AND t.id=e.task_id AND t.visibility='workspace'))) THEN\n      unknowns := unknowns || jsonb_build_array(jsonb_build_object('kind','source_audience_unavailable_at_capture','episode_id',e.id));\n    END IF;\n    IF e.connection_id IS NOT NULL AND NOT EXISTS (SELECT FROM app.connections c WHERE c.workspace_id=ws\n        AND c.id=e.connection_id AND (c.scope='workspace' OR c.owner_id=(p_claim).on_behalf_of)) THEN\n      unknowns := unknowns || jsonb_build_array(jsonb_build_object('kind','connection_audience_unavailable_at_capture','episode_id',e.id));\n    END IF;\n    reserved := e.source_kind = 'mcp' OR (e.source_kind = 'file' AND left(e.source_ref,9) COLLATE \"C\" = 'material:');\n    receipt := NULL;\n    registrations := '[]'::jsonb;\n    material_state := NULL;\n    IF reserved THEN\n      material_state := gov._material_source_projection(e.id);\n      SELECT r.* INTO receipt FROM app.material_source_reads r WHERE r.workspace_id=ws AND r.episode_id=e.id;\n      IF receipt.receipt_id IS NOT NULL THEN\n        SELECT count(*), coalesce(jsonb_agg(jsonb_build_object('seq',x.seq::text,'actor_id',x.actor_id,\n          'payload',x.payload,'prev_hash',x.prev_hash,'hash',x.hash) ORDER BY x.seq), '[]'::jsonb)\n        INTO n, registrations FROM app.ledger x WHERE x.workspace_id=ws\n          AND x.entry_type='material.read_registered' AND x.subject=receipt.receipt_id::text AND x.seq<=p_capture_seq;\n        IF n <> 1 OR EXISTS (SELECT FROM app.ledger x WHERE x.workspace_id=ws\n            AND x.entry_type='material.read_registered' AND x.subject=receipt.receipt_id::text\n            AND (x.seq>p_capture_seq OR x.actor_id IS DISTINCT FROM receipt.recorded_by\n              OR x.payload IS DISTINCT FROM jsonb_build_object('episode',e.id,'read_key',sec.digest(receipt.read_key),\n                'project',sec.digest(receipt.project_id),'material',sec.digest(receipt.material_id),\n                'version',receipt.material_version,'generation',receipt.generation,'kind',receipt.source_kind,\n                'original_sha256',sec.digest(receipt.original_sha256),'transformation',sec.digest(receipt.transformation::text),\n                'episode_sha256',sec.digest(receipt.episode_sha256),'prepared_sha256',sec.digest(receipt.prepared_sha256))\n              OR x.hash IS DISTINCT FROM sec.ledger_hash(x.prev_hash,x.workspace_id,x.seq,x.entry_type,x.actor_id,x.subject,x.payload,x.at)\n              OR NOT EXISTS (SELECT FROM app.ledger prev WHERE prev.workspace_id=ws AND prev.seq=x.seq-1 AND prev.hash=x.prev_hash))) THEN\n          unknowns := unknowns || jsonb_build_array(jsonb_build_object('kind','material_registration_history_not_demonstrated','episode_id',e.id));\n        END IF;\n      END IF;\n      IF material_state IS DISTINCT FROM 'live' THEN\n        unknowns := unknowns || jsonb_build_array(jsonb_build_object('kind','material_not_live_at_capture',\n          'episode_id',e.id,'state',material_state));\n      END IF;\n    END IF;\n    sources := sources || jsonb_build_array(jsonb_build_object(\n      'episode_id',e.id,'source_kind',e.source_kind,'source_ref_digest',sec.digest(e.source_ref),\n      'trust',e.trust,'recorded_sensitive',e.sensitive,'recorded_by',e.recorded_by,'authored_by',e.authored_by,\n      'run_id',e.run_id,'task_id',e.task_id,'document_id',e.document_id,'document_version',e.document_version,\n      'connection_id',e.connection_id,'content_sha256',e.content_hash,'citations',citations,\n      'recordings',recordings,'material_state_at_capture',material_state,\n      'material_receipt', CASE WHEN receipt.receipt_id IS NULL THEN NULL::jsonb ELSE\n        -- Full native receipt identities/hashes; omit caller-controlled transformation words/tool.\n        jsonb_build_object('receipt_id',receipt.receipt_id,'read_key_digest',sec.digest(receipt.read_key),\n          'material_id',receipt.material_id,'project_id',receipt.project_id,'version',receipt.material_version,\n          'generation',receipt.generation,'original_sha256',receipt.original_sha256,\n          'transformation_digest',sec.digest(receipt.transformation::text),'episode_sha256',receipt.episode_sha256,\n          'prepared_sha256',receipt.prepared_sha256,'source_kind',receipt.source_kind,'authored_by',receipt.authored_by,\n          'run_id',receipt.run_id,'requested_task_id',receipt.requested_task_id,'connection_id',receipt.connection_id,\n          'tool_digest',sec.digest(receipt.tool),'recorded_by',receipt.recorded_by) END,\n      'material_registrations',registrations));\n  END LOOP;\n\n  IF (p_claim).run_id IS NOT NULL THEN\n    SELECT x.* INTO native_run FROM app.runs x WHERE x.workspace_id=ws AND x.id=(p_claim).run_id;\n    edges := edges || jsonb_build_array(jsonb_build_object('kind','native_run_taint_observation',\n      'run_id',native_run.id,'tainted_untrusted',native_run.tainted_untrusted,\n      'tainted_sensitive',native_run.tainted_sensitive,'untrusted_reason_digest',sec.digest(native_run.untrusted_source),\n      'sensitive_reason_digest',sec.digest(native_run.sensitive_source),'elsewhere_reason_digest',sec.digest(native_run.elsewhere_source)));\n    -- Preserve every typed recall, including full inherited closure, never merely its taint.\n    FOR k IN SELECT r.* FROM app.knowledge_reads r WHERE r.workspace_id=ws\n      AND r.receiving_run_id=(p_claim).run_id AND r.read_seq<=p_capture_seq ORDER BY r.read_seq,r.batch_ordinal,r.read_id LOOP\n      edges := edges || jsonb_build_array(jsonb_build_object('kind','native_knowledge_read','row',to_jsonb(k)));\n      IF k.read_seq > p_capture_seq OR k.source_sha256 IS DISTINCT FROM\n          encode(sha256(convert_to(k.source_snapshot::text,'UTF8')),'hex')\n          OR NOT EXISTS (SELECT FROM app.ledger x WHERE x.workspace_id=ws AND x.seq=k.read_seq\n            AND x.entry_type='knowledge.recalled' AND x.subject=k.batch_id::text\n            AND x.actor_id=k.receiving_agent_id AND x.payload -> 'version' = '1'::jsonb\n            AND x.payload ->> 'run'=k.receiving_run_id::text AND x.payload ->> 'fence'=k.receiving_fence::text\n            AND x.payload -> 'reads' @> jsonb_build_array(jsonb_build_object('read',k.read_id,\n              'knowledge',k.knowledge_id,'candidate',k.candidate_id,'source',k.source_sha256))\n            AND x.hash=sec.ledger_hash(x.prev_hash,x.workspace_id,x.seq,x.entry_type,x.actor_id,x.subject,x.payload,x.at)\n            AND EXISTS (SELECT FROM app.ledger prev WHERE prev.workspace_id=ws AND prev.seq=x.seq-1 AND prev.hash=x.prev_hash)) THEN\n        unknowns := unknowns || jsonb_build_array(jsonb_build_object('kind','knowledge_read_history_not_demonstrated','read_id',k.read_id));\n      END IF;\n    END LOOP;\n    -- Include original native event facts even when the corresponding episode/read is absent.\n    -- These are observations, not a claim that every historically delivered output was traced.\n    FOR l IN SELECT x.* FROM app.ledger x WHERE x.workspace_id=ws AND x.seq<=p_capture_seq\n      AND x.entry_type IN ('source.recorded','knowledge.recalled')\n      AND x.payload ->> 'run'=(p_claim).run_id::text ORDER BY x.seq LOOP\n      edges := edges || jsonb_build_array(jsonb_build_object('kind','native_input_event','seq',l.seq::text,\n        'entry_type',l.entry_type,'subject',l.subject,'actor_id',l.actor_id,\n        'payload',l.payload,'prev_hash',l.prev_hash,'hash',l.hash));\n      IF (l.entry_type='source.recorded' AND NOT EXISTS (SELECT FROM app.episodes x WHERE x.workspace_id=ws AND x.id::text=l.subject))\n        OR (l.entry_type='knowledge.recalled' AND l.payload -> 'reads' IS DISTINCT FROM '[]'::jsonb AND NOT EXISTS (SELECT FROM app.knowledge_reads x WHERE x.workspace_id=ws AND x.batch_id::text=l.subject)) THEN\n        unknowns := unknowns || jsonb_build_array(jsonb_build_object('kind','input_event_missing_native_row','seq',l.seq::text));\n      END IF;\n    END LOOP;\n  END IF;\n  RETURN jsonb_build_object('version',1,'complete',false,'sources',sources,'read_edges',edges,'unknown',unknowns);\nEND\n$$;\nALTER FUNCTION gov._candidate_input_manifest_v1(app.knowledge_candidates,bigint) OWNER TO backbone_gov;\nREVOKE ALL ON FUNCTION gov._candidate_input_manifest_v1(app.knowledge_candidates,bigint)\n  FROM PUBLIC, backbone_app, backbone_operator;\n\n-- sec/t_candidate_input_capture_v1.sql\n\n-- Material closure foundation v1. Canonical versioned source; see its closed manifest.\nCREATE FUNCTION sec.t_candidate_input_capture_v1() RETURNS trigger\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE\n  ws uuid;\n  actor uuid;\n  native_run uuid;\n  beneficiary uuid;\n  r app.runs%ROWTYPE;\n  e app.episodes%ROWTYPE;\n  source_run_task uuid;\n  connection app.connections%ROWTYPE;\n  boundary app.ledger%ROWTYPE;\n  captured app.ledger%ROWTYPE;\n  head app.ledger_heads%ROWTYPE;\n  citation jsonb;\n  matches bigint;\n  cited_untrusted boolean := false;\n  manifest jsonb;\n  claim_digest text;\n  reserved boolean;\nBEGIN\n  IF TG_OP <> 'INSERT' OR TG_TABLE_SCHEMA <> 'app' OR TG_TABLE_NAME <> 'knowledge_candidates' THEN\n    RAISE EXCEPTION 'invalid: candidate input capture belongs only to candidate insertion';\n  END IF;\n  IF current_setting('transaction_isolation') <> 'read committed' THEN\n    RAISE EXCEPTION 'paused: candidate input capture requires READ COMMITTED isolation';\n  END IF;\n  -- No actor/run/source read before the waiting statement. All authority is rederived later.\n  PERFORM gov._lock_workspace();\n  ws := sec.current_workspace();\n  IF ws IS NULL OR NEW.workspace_id IS DISTINCT FROM ws THEN\n    RAISE EXCEPTION 'no_identity: candidate capture requires its native workspace';\n  END IF;\n  actor := sec.current_principal();\n  native_run := sec.current_run();\n  IF actor IS NULL OR (sec.names_run() AND native_run IS NULL)\n     OR NEW.proposed_by IS DISTINCT FROM actor OR NEW.run_id IS DISTINCT FROM native_run THEN\n    RAISE EXCEPTION 'stale: candidate identity no longer matches the authenticated native actor and run';\n  END IF;\n  IF NEW.id IS NULL OR EXISTS (SELECT FROM app.knowledge_candidates c WHERE c.workspace_id=ws AND c.id=NEW.id)\n     OR EXISTS (SELECT FROM app.knowledge_candidate_inputs p WHERE p.workspace_id=ws AND p.candidate_id=NEW.id)\n     OR EXISTS (SELECT FROM app.ledger l WHERE l.workspace_id=ws AND l.entry_type='knowledge.proposed' AND l.subject=NEW.id::text) THEN\n    RAISE EXCEPTION 'conflict: candidate capture requires a new candidate, proof and proposal identity';\n  END IF;\n  IF NEW.status IS DISTINCT FROM 'open' OR NEW.owner_id IS NOT NULL OR NEW.valid_from IS NOT NULL\n     OR NEW.valid_to IS NOT NULL OR NEW.terms_hash IS NOT NULL THEN\n    RAISE EXCEPTION 'invalid: candidate creation grants no acceptance or terms';\n  END IF;\n  IF NEW.statement IS NULL OR length(NEW.statement) NOT BETWEEN 1 AND 4000 OR NEW.topic IS NULL\n     OR NEW.created_at IS NULL OR jsonb_typeof(NEW.evidence) IS DISTINCT FROM 'array'\n     OR jsonb_array_length(NEW.evidence)=0 THEN\n    RAISE EXCEPTION 'invalid: a candidate states a claim and cites recorded sources';\n  END IF;\n  IF native_run IS NOT NULL THEN\n    BEGIN\n      -- Older native recorders may own run before head. Never wait in the reverse order.\n      SELECT x.* INTO r FROM app.runs x WHERE x.workspace_id=ws AND x.id=native_run FOR UPDATE NOWAIT;\n    EXCEPTION WHEN lock_not_available THEN\n      RAISE EXCEPTION 'paused: candidate run is changing; retry after its native owner settles';\n    END;\n    IF NOT FOUND THEN RAISE EXCEPTION 'stale: candidate run no longer exists'; END IF;\n    r := gov._holder(native_run,r.fence);\n    IF gov.run_standing(native_run) IS DISTINCT FROM 'ok' OR r.status IS DISTINCT FROM 'running'\n       OR r.agent_id IS DISTINCT FROM actor THEN\n      RAISE EXCEPTION 'stale: candidate run no longer has native standing';\n    END IF;\n    beneficiary := gov._run_person(native_run);\n    IF beneficiary IS NULL OR NOT EXISTS (SELECT FROM app.principals p WHERE p.workspace_id=ws\n         AND p.id=beneficiary AND p.kind='person' AND p.status='active')\n       OR NOT sec.task_visible_to(r.task_id,beneficiary) THEN\n      RAISE EXCEPTION 'denied: candidate run has no current authorised native beneficiary';\n    END IF;\n  ELSE\n    -- A standalone agent stays an agent; its owner is an audience, not a personal declaration.\n    beneficiary := sec.acting_for();\n    IF beneficiary IS NOT NULL AND NOT EXISTS (SELECT FROM app.principals p WHERE p.workspace_id=ws\n         AND p.id=beneficiary AND p.kind='person' AND p.status='active') THEN\n      RAISE EXCEPTION 'denied: candidate has no active native receiving person';\n    END IF;\n  END IF;\n  NEW.created_at := clock_timestamp();\n  NEW.proposed_by := actor;\n  NEW.run_id := native_run;\n  NEW.on_behalf_of := beneficiary;\n\n  SELECT count(*) INTO matches FROM app.ledger l WHERE l.workspace_id=ws\n    AND l.entry_type='knowledge.dependencies_enabled';\n  IF matches<>1 THEN RAISE EXCEPTION 'paused: candidate needs one native dependency boundary'; END IF;\n  SELECT l.* INTO boundary FROM app.ledger l WHERE l.workspace_id=ws\n    AND l.entry_type='knowledge.dependencies_enabled';\n  SELECT h.* INTO head FROM app.ledger_heads h WHERE h.workspace_id=ws;\n  SELECT l.* INTO captured FROM app.ledger l WHERE l.workspace_id=ws AND l.seq=head.last_seq;\n  IF NOT FOUND OR boundary.subject IS NOT NULL\n     OR boundary.payload IS DISTINCT FROM jsonb_build_object('version','material-closure-foundation-v1')\n     OR boundary.seq>captured.seq OR captured.seq>=9223372036854775807\n     OR head.last_hash IS DISTINCT FROM captured.hash\n     OR boundary.hash IS DISTINCT FROM sec.ledger_hash(boundary.prev_hash,boundary.workspace_id,boundary.seq,\n       boundary.entry_type,boundary.actor_id,boundary.subject,boundary.payload,boundary.at)\n     OR captured.hash IS DISTINCT FROM sec.ledger_hash(captured.prev_hash,captured.workspace_id,captured.seq,\n       captured.entry_type,captured.actor_id,captured.subject,captured.payload,captured.at) THEN\n    RAISE EXCEPTION 'paused: candidate boundary or captured native head is inconsistent';\n  END IF;\n\n  FOR citation IN SELECT value FROM jsonb_array_elements(NEW.evidence) LOOP\n    IF jsonb_typeof(citation) IS DISTINCT FROM 'object' THEN\n      RAISE EXCEPTION 'invalid: candidate citations are native episode and excerpt objects';\n    END IF;\n    IF jsonb_typeof(citation -> 'episode') IS DISTINCT FROM 'string'\n       OR jsonb_typeof(citation -> 'excerpt') IS DISTINCT FROM 'string'\n       OR (SELECT count(*) FROM jsonb_object_keys(citation))<>2\n       OR citation ->> 'episode' !~ '^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$' THEN\n      RAISE EXCEPTION 'invalid: candidate citations have exact native episode and excerpt fields';\n    END IF;\n    SELECT x.* INTO e FROM app.episodes x WHERE x.workspace_id=ws AND x.id=(citation ->> 'episode')::uuid;\n    -- Proposal captures inputs; the released promotion crossing checks literal evidence.\n    -- A mismatch is retained in the immutable manifest and cannot certify personal lineage.\n    IF NOT FOUND OR e.content_hash IS DISTINCT FROM encode(sha256(convert_to(e.content,'UTF8')),'hex') THEN\n      RAISE EXCEPTION 'invalid: candidate source is missing or its recorded content hash is inconsistent';\n    END IF;\n    cited_untrusted := cited_untrusted OR e.trust='untrusted';\n    -- Never use System-recorder visibility or same-run identity as an audience exemption.\n    IF e.task_id IS NOT NULL AND NOT (\n         (beneficiary IS NOT NULL AND sec.task_visible_to(e.task_id,beneficiary))\n         OR (beneficiary IS NULL AND EXISTS (SELECT FROM app.tasks t WHERE t.workspace_id=ws\n           AND t.id=e.task_id AND t.visibility='workspace'))) THEN\n      RAISE EXCEPTION 'denied: candidate citation is outside its receiving audience';\n    END IF;\n    IF e.run_id IS NOT NULL THEN\n      SELECT x.task_id INTO source_run_task FROM app.runs x WHERE x.workspace_id=ws AND x.id=e.run_id;\n      IF NOT FOUND OR NOT ((beneficiary IS NOT NULL AND sec.task_visible_to(source_run_task,beneficiary))\n          OR (beneficiary IS NULL AND EXISTS (SELECT FROM app.tasks t WHERE t.workspace_id=ws\n            AND t.id=source_run_task AND t.visibility='workspace'))) THEN\n        RAISE EXCEPTION 'denied: candidate source run is outside its receiving audience';\n      END IF;\n    END IF;\n    IF e.connection_id IS NOT NULL THEN\n      SELECT x.* INTO connection FROM app.connections x WHERE x.workspace_id=ws AND x.id=e.connection_id;\n      IF NOT FOUND OR (connection.scope='person' AND connection.owner_id IS DISTINCT FROM beneficiary) THEN\n        RAISE EXCEPTION 'denied: candidate connected source belongs to another audience';\n      END IF;\n    END IF;\n    IF e.source_kind='message' AND e.source_ref ~ '^message:[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$'\n       AND EXISTS (SELECT FROM app.messages m WHERE m.workspace_id=ws\n         AND m.id=substring(e.source_ref FROM 9)::uuid AND m.only_for IS NOT NULL\n         AND m.only_for IS DISTINCT FROM beneficiary) THEN\n      RAISE EXCEPTION 'denied: candidate message is kept for another person';\n    END IF;\n    reserved := e.source_kind='mcp' OR (e.source_kind='file' AND left(e.source_ref,9) COLLATE \"C\"='material:');\n    IF reserved AND gov._material_source_projection(e.id) IS DISTINCT FROM 'live' THEN\n      RAISE EXCEPTION 'paused: cited material is withdrawn or its native binding is unknown';\n    END IF;\n  END LOOP;\n  -- Preserve the released candidate semantics, now from post-lock native facts.\n  -- Incomplete lineage is represented independently; false taint is never a clean proof.\n  NEW.words_untrusted := cited_untrusted OR CASE WHEN native_run IS NULL THEN false ELSE r.tainted_untrusted END;\n  NEW.kept := CASE WHEN native_run IS NULL THEN false ELSE r.tainted_untrusted AND r.tainted_sensitive END;\n  claim_digest := gov._candidate_claim_digest_v1(NEW::app.knowledge_candidates);\n  IF claim_digest IS NULL OR claim_digest !~ '^[a-f0-9]{64}$' THEN\n    RAISE EXCEPTION 'paused: candidate claim digest is unavailable';\n  END IF;\n  manifest := gov._candidate_input_manifest_v1(NEW::app.knowledge_candidates,captured.seq);\n  IF EXISTS (SELECT FROM jsonb_array_elements(manifest -> 'unknown') u\n      WHERE u ->> 'kind' IN ('source_history_not_demonstrated','material_registration_history_not_demonstrated')\n        AND EXISTS (SELECT FROM jsonb_array_elements(NEW.evidence) c WHERE c ->> 'episode'=u ->> 'episode_id')\n        AND EXISTS (SELECT FROM app.episodes x WHERE x.workspace_id=ws AND x.id::text=u ->> 'episode_id'\n          AND (x.source_kind='mcp' OR (x.source_kind='file' AND left(x.source_ref,9) COLLATE \"C\"='material:')))) THEN\n    RAISE EXCEPTION 'paused: cited material has no unambiguous native read history';\n  END IF;\n  -- Always fresh INSERT, no conflict recovery, no reuse, no backfill. Same-statement\n  -- failure rolls back this proof; deferred candidate FK permits the BEFORE ordering.\n  INSERT INTO app.knowledge_candidate_inputs(workspace_id,candidate_id,format_version,\n    boundary_seq,boundary_hash,capture_seq,capture_hash,proposed_by,run_id,run_fence,run_task_id,\n    on_behalf_of,run_tainted_untrusted,run_tainted_sensitive,words_untrusted,kept,\n    claim_digest,input_manifest,input_sha256)\n  VALUES(ws,NEW.id,1,boundary.seq,boundary.hash,captured.seq,captured.hash,actor,native_run,\n    CASE WHEN native_run IS NULL THEN NULL ELSE r.fence END,\n    CASE WHEN native_run IS NULL THEN NULL ELSE r.task_id END,beneficiary,\n    CASE WHEN native_run IS NULL THEN NULL ELSE r.tainted_untrusted END,\n    CASE WHEN native_run IS NULL THEN NULL ELSE r.tainted_sensitive END,NEW.words_untrusted,NEW.kept,\n    claim_digest,manifest,encode(sha256(convert_to(manifest::text,'UTF8')),'hex'));\n  -- No _append here: the old body must append knowledge.proposed immediately at H+1.\n  RETURN NEW;\nEND\n$$;\nALTER FUNCTION sec.t_candidate_input_capture_v1() OWNER TO backbone_gov;\nREVOKE ALL ON FUNCTION sec.t_candidate_input_capture_v1() FROM PUBLIC, backbone_app, backbone_operator;\nGRANT EXECUTE ON FUNCTION sec.t_candidate_input_capture_v1() TO backbone_owner;\n\n-- sec/t_candidate_input_structure.sql\n\n-- Material closure foundation v1. Canonical versioned source; see its closed manifest.\nCREATE FUNCTION sec.t_candidate_input_structure() RETURNS trigger\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE\n  candidate app.knowledge_candidates%ROWTYPE;\n  proof app.knowledge_candidate_inputs%ROWTYPE;\n  boundary app.ledger%ROWTYPE;\n  captured app.ledger%ROWTYPE;\n  proposal app.ledger%ROWTYPE;\n  entries bigint;\nBEGIN\n  IF TG_OP <> 'INSERT' OR TG_TABLE_SCHEMA <> 'app' OR TG_TABLE_NAME <> 'knowledge_candidates' THEN\n    RAISE EXCEPTION 'invalid: candidate input validation belongs only to candidate insertion';\n  END IF;\n  IF current_setting('transaction_isolation') <> 'read committed' THEN\n    RAISE EXCEPTION 'paused: candidate input validation requires READ COMMITTED isolation';\n  END IF;\n  -- These tenant-walled reads require the original workspace at validation. Do not manufacture\n  -- another workspace context, or use the current principal as the historical creation actor.\n  IF NEW.workspace_id IS DISTINCT FROM sec.current_workspace() THEN\n    RAISE EXCEPTION 'paused: candidate input validation requires its original workspace';\n  END IF;\n  PERFORM gov._lock_workspace();\n  SELECT c.* INTO candidate FROM app.knowledge_candidates c\n  WHERE c.workspace_id = NEW.workspace_id AND c.id = NEW.id;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'paused: the candidate row is missing at input validation';\n  END IF;\n  SELECT p.* INTO proof FROM app.knowledge_candidate_inputs p\n  WHERE p.workspace_id = candidate.workspace_id AND p.candidate_id = candidate.id;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'paused: the candidate has no native input proof';\n  END IF;\n  IF proof.format_version IS DISTINCT FROM 1\n     OR proof.proposed_by IS DISTINCT FROM candidate.proposed_by\n     OR proof.run_id IS DISTINCT FROM candidate.run_id\n     OR proof.on_behalf_of IS DISTINCT FROM candidate.on_behalf_of\n     OR proof.words_untrusted IS DISTINCT FROM candidate.words_untrusted\n     OR proof.kept IS DISTINCT FROM candidate.kept\n     OR proof.claim_digest IS DISTINCT FROM gov._candidate_claim_digest_v1(candidate)\n     OR proof.input_sha256 IS DISTINCT FROM encode(sha256(convert_to(proof.input_manifest::text, 'UTF8')), 'hex') THEN\n    RAISE EXCEPTION 'paused: candidate input proof does not bind its immutable claim';\n  END IF;\n  SELECT count(*) INTO entries FROM app.ledger l\n  WHERE l.workspace_id = candidate.workspace_id AND l.entry_type = 'knowledge.dependencies_enabled';\n  IF entries <> 1 THEN\n    RAISE EXCEPTION 'paused: the candidate workspace has no unique native input boundary';\n  END IF;\n  SELECT l.* INTO boundary FROM app.ledger l\n  WHERE l.workspace_id = candidate.workspace_id AND l.seq = proof.boundary_seq;\n  IF NOT FOUND OR boundary.entry_type IS DISTINCT FROM 'knowledge.dependencies_enabled'\n     OR boundary.subject IS NOT NULL\n     OR boundary.payload IS DISTINCT FROM jsonb_build_object('version', 'material-closure-foundation-v1')\n     OR boundary.hash IS DISTINCT FROM proof.boundary_hash\n     OR proof.capture_seq < proof.boundary_seq THEN\n    RAISE EXCEPTION 'paused: candidate input proof has a mismatched native boundary';\n  END IF;\n  SELECT l.* INTO captured FROM app.ledger l\n  WHERE l.workspace_id = candidate.workspace_id AND l.seq = proof.capture_seq;\n  IF NOT FOUND OR captured.hash IS DISTINCT FROM proof.capture_hash THEN\n    RAISE EXCEPTION 'paused: candidate input proof has no matching captured ledger head';\n  END IF;\n  SELECT count(*) INTO entries FROM app.ledger l\n  WHERE l.workspace_id = candidate.workspace_id AND l.entry_type = 'knowledge.proposed'\n    AND l.subject = candidate.id::text;\n  IF entries <> 1 THEN\n    RAISE EXCEPTION 'paused: the candidate requires exactly one matching proposal event';\n  END IF;\n  SELECT l.* INTO proposal FROM app.ledger l\n  WHERE l.workspace_id = candidate.workspace_id AND l.seq = proof.proposal_seq;\n  IF NOT FOUND OR proposal.entry_type IS DISTINCT FROM 'knowledge.proposed'\n     OR proposal.subject IS DISTINCT FROM candidate.id::text\n     OR proposal.actor_id IS DISTINCT FROM proof.proposed_by\n     OR proposal.prev_hash IS DISTINCT FROM proof.capture_hash\n     OR proposal.hash IS DISTINCT FROM sec.ledger_hash(proposal.prev_hash, proposal.workspace_id,\n       proposal.seq, proposal.entry_type, proposal.actor_id, proposal.subject, proposal.payload, proposal.at) THEN\n    RAISE EXCEPTION 'paused: the proposal event does not immediately follow its native input cut';\n  END IF;\n  -- The released body digests raw p_topic; NULL becomes stored topic 'general' but event topic\n  -- JSON null. Accept exactly those two encodings of the same stored general topic.\n  IF proposal.payload IS DISTINCT FROM jsonb_build_object('run', proof.run_id, 'topic', sec.digest(candidate.topic))\n     AND NOT (candidate.topic = 'general'\n       AND proposal.payload IS NOT DISTINCT FROM jsonb_build_object('run', proof.run_id, 'topic', NULL::text)) THEN\n    RAISE EXCEPTION 'paused: the proposal payload does not bind its native run and topic';\n  END IF;\n  RETURN NEW;\nEND\n$$;\nREVOKE ALL ON FUNCTION sec.t_candidate_input_structure()\n  FROM PUBLIC, backbone_app, backbone_operator;\nGRANT EXECUTE ON FUNCTION sec.t_candidate_input_structure() TO backbone_owner;\n\n-- gov/_knowledge_personal_closure_v1.sql\n\n-- Material closure foundation v1. Canonical versioned source; see its closed manifest.\nCREATE FUNCTION gov._knowledge_personal_closure_v1(p_candidate uuid, p_receiver uuid)\nRETURNS jsonb\nLANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE\n  ws uuid := sec.current_workspace();\n  unavailable jsonb := jsonb_build_object('format','candidate-personal-closure-v1','state','unknown');\n  roots jsonb;\n  immutable_sources jsonb;\n  expected_manifest jsonb;\n  c app.knowledge_candidates%ROWTYPE;\n  proof app.knowledge_candidate_inputs%ROWTYPE;\n  boundary app.ledger%ROWTYPE;\n  captured app.ledger%ROWTYPE;\n  proposal app.ledger%ROWTYPE;\n  entries bigint;\n  has_proof boolean;\nBEGIN\n  roots := gov._personal_message_roots_v1(p_candidate, p_receiver);\n  IF roots ->> 'state' IS DISTINCT FROM 'known_personal_roots' THEN\n    RETURN unavailable || jsonb_build_object('reason','personal_roots_unknown');\n  END IF;\n  SELECT * INTO c FROM app.knowledge_candidates x WHERE x.workspace_id=ws AND x.id=p_candidate;\n  IF NOT FOUND OR roots ->> 'claim_digest' IS NULL\n     OR roots ->> 'claim_digest' !~ '^[a-f0-9]{64}$'\n     OR roots ->> 'claim_digest' IS DISTINCT FROM gov._candidate_claim_digest_v1(c) THEN\n    RETURN unavailable || jsonb_build_object('reason','claim_binding_unknown');\n  END IF;\n  -- This family is explicitly MESSAGE only. Adding WEB requires its own native positive\n  -- producer proof; an allowlist entry alone never certifies an exact native source.\n  IF EXISTS (SELECT FROM jsonb_array_elements(roots -> 'roots') r\n             WHERE r ->> 'source_kind' IS DISTINCT FROM 'message') THEN\n    RETURN unavailable || jsonb_build_object('reason','unsupported_source_kind');\n  END IF;\n  SELECT count(*) INTO entries FROM app.ledger l\n  WHERE l.workspace_id=ws AND l.entry_type='knowledge.dependencies_enabled';\n  IF entries <> 1 THEN\n    RETURN unavailable || jsonb_build_object('reason','boundary_unknown');\n  END IF;\n  SELECT * INTO boundary FROM app.ledger l\n  WHERE l.workspace_id=ws AND l.entry_type='knowledge.dependencies_enabled';\n  IF boundary.subject IS NOT NULL\n     OR boundary.payload IS DISTINCT FROM jsonb_build_object('version','material-closure-foundation-v1')\n     OR boundary.hash IS DISTINCT FROM sec.ledger_hash(boundary.prev_hash,ws,boundary.seq,\n       boundary.entry_type,boundary.actor_id,boundary.subject,boundary.payload,boundary.at)\n     OR NOT EXISTS (SELECT FROM app.ledger l WHERE l.workspace_id=ws\n       AND l.seq=boundary.seq-1 AND l.hash=boundary.prev_hash) THEN\n    RETURN unavailable || jsonb_build_object('reason','boundary_binding_unknown');\n  END IF;\n  -- Frozen roots already require the unique real proposal event and its exact claim,\n  -- own hash and predecessor. Re-select by that identity, never parse a reason string.\n  SELECT * INTO proposal FROM app.ledger l WHERE l.workspace_id=ws\n    AND l.entry_type='knowledge.proposed' AND l.subject=c.id::text;\n  IF NOT FOUND OR proposal.seq::text IS DISTINCT FROM roots ->> 'proposal_seq' THEN\n    RETURN unavailable || jsonb_build_object('reason','proposal_binding_unknown');\n  END IF;\n  SELECT * INTO proof FROM app.knowledge_candidate_inputs p\n    WHERE p.workspace_id=ws AND p.candidate_id=c.id;\n  has_proof := FOUND;\n  IF NOT has_proof THEN\n    IF proposal.seq >= boundary.seq THEN\n      RETURN unavailable || jsonb_build_object('reason','post_boundary_proof_missing');\n    END IF;\n    -- A legacy standalone personal declaration has a positively demonstrated native cut.\n    -- This derives a present read snapshot; it never backfills a creation-time proof.\n    RETURN jsonb_build_object('format','candidate-personal-closure-v1',\n      'state','known_personal_closure','basis','legacy_exact_native_cut',\n      'boundary_seq',boundary.seq::text,'boundary_hash',boundary.hash,\n      'proof',NULL,'roots',roots);\n  END IF;\n  IF proof.format_version IS DISTINCT FROM 1 OR proof.boundary_seq <> boundary.seq\n     OR proof.boundary_hash IS DISTINCT FROM boundary.hash\n     OR proof.capture_seq < boundary.seq OR proof.proposal_seq <> proposal.seq\n     OR proposal.seq <> proof.capture_seq+1\n     OR proof.proposed_by IS DISTINCT FROM c.proposed_by\n     OR proof.run_id IS NOT NULL OR proof.run_fence IS NOT NULL OR proof.run_task_id IS NOT NULL\n     OR proof.run_tainted_untrusted IS NOT NULL OR proof.run_tainted_sensitive IS NOT NULL\n     OR proof.on_behalf_of IS DISTINCT FROM c.on_behalf_of\n     OR proof.words_untrusted IS DISTINCT FROM c.words_untrusted\n     OR proof.kept IS DISTINCT FROM c.kept\n     OR proof.claim_digest IS DISTINCT FROM roots ->> 'claim_digest'\n     OR proof.input_sha256 IS DISTINCT FROM encode(sha256(convert_to(proof.input_manifest::text,'UTF8')),'hex') THEN\n    RETURN unavailable || jsonb_build_object('reason','native_proof_binding_unknown');\n  END IF;\n  SELECT * INTO captured FROM app.ledger l WHERE l.workspace_id=ws AND l.seq=proof.capture_seq;\n  IF NOT FOUND OR captured.hash IS DISTINCT FROM proof.capture_hash\n     OR captured.hash IS DISTINCT FROM sec.ledger_hash(captured.prev_hash,ws,captured.seq,\n       captured.entry_type,captured.actor_id,captured.subject,captured.payload,captured.at)\n     OR NOT EXISTS (SELECT FROM app.ledger l WHERE l.workspace_id=ws\n       AND l.seq=captured.seq-1 AND l.hash=captured.prev_hash)\n     OR proposal.prev_hash IS DISTINCT FROM captured.hash THEN\n    RETURN unavailable || jsonb_build_object('reason','native_capture_cut_unknown');\n  END IF;\n  -- The original native BEFORE guard authenticated the active proposer and their audience\n  -- AT CAPTURE. Do not replay those mutable admissions against today's proposer status.\n  -- The full native roots result above independently enforces TODAY'S receiving person,\n  -- visibility and sensitivity and validates each immutable message/episode/event/claim.\n  -- Its positive proposal cut is now structurally bound to original H+1. Keep every root,\n  -- explicitly require both actual source/message cuts <= H, and normalise ONLY the\n  -- current sensitivity field out of the historical comparison. No caller JSON is used.\n  IF jsonb_array_length(roots -> 'roots') NOT BETWEEN 1 AND 64\n     OR EXISTS (SELECT FROM jsonb_array_elements(roots -> 'roots') source\n       WHERE (source ->> 'message_seq')::bigint < 1\n         OR (source ->> 'source_seq')::bigint < 1\n         OR (source ->> 'message_seq')::bigint > proof.capture_seq\n         OR (source ->> 'source_seq')::bigint > proof.capture_seq\n         OR (source ->> 'message_seq')::bigint >= (source ->> 'source_seq')::bigint) THEN\n    RETURN unavailable || jsonb_build_object('reason','personal_proof_inputs_unknown',\n      'detail','original_native_source_cut_not_demonstrated');\n  END IF;\n  SELECT jsonb_agg(source - 'currently_sensitive'\n    ORDER BY (source ->> 'episode_id') COLLATE \"C\") INTO immutable_sources\n    FROM jsonb_array_elements(roots -> 'roots') source;\n  expected_manifest := jsonb_build_object('version',1,'complete',true,\n    'sources',immutable_sources,'read_edges','[]'::jsonb,'unknown','[]'::jsonb);\n  -- Shape/hash/complete=true alone is NEVER sufficient. Compare the entire stored proof\n  -- to native source rederivation; extra omitted/unsupported dependencies cannot disappear.\n  IF proof.input_manifest IS DISTINCT FROM expected_manifest THEN\n    RETURN unavailable || jsonb_build_object('reason','personal_proof_manifest_unknown');\n  END IF;\n  RETURN jsonb_build_object('format','candidate-personal-closure-v1',\n    'state','known_personal_closure','basis','native_before_personal_proof',\n    'boundary_seq',boundary.seq::text,'boundary_hash',boundary.hash,\n    'proof',jsonb_build_object('candidate_id',proof.candidate_id,\n      'format_version',proof.format_version,'claim_digest',proof.claim_digest,\n      'capture_seq',proof.capture_seq::text,'capture_hash',proof.capture_hash,\n      'proposal_seq',proof.proposal_seq::text,'input_sha256',proof.input_sha256,\n      'input_manifest',proof.input_manifest),\n    'roots',roots);\nEND\n$$;\nALTER FUNCTION gov._knowledge_personal_closure_v1(uuid,uuid) OWNER TO backbone_gov;\nREVOKE ALL ON FUNCTION gov._knowledge_personal_closure_v1(uuid,uuid)\n  FROM PUBLIC,backbone_app,backbone_operator;\n\n-- gov/recall_knowledge_traced_v1.sql\n\n-- Material closure foundation v1. Canonical versioned source; see its closed manifest.\nCREATE FUNCTION gov.recall_knowledge_traced_v1(\n  p_run uuid, p_fence bigint, p_words text[], p_limit integer\n) RETURNS TABLE(read_id uuid, knowledge_id uuid, candidate_id uuid, read_seq bigint, statement text, topic text)\nLANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE\n  ws uuid;\n  r app.runs%ROWTYPE;\n  person uuid;\n  k app.knowledge%ROWTYPE;\n  c app.knowledge_candidates%ROWTYPE;\n  accepted app.ledger%ROWTYPE;\n  closure jsonb;\n  snapshot jsonb;\n  ids uuid[] := ARRAY[]::uuid[];\n  knowledge_ids uuid[] := ARRAY[]::uuid[];\n  candidate_ids uuid[] := ARRAY[]::uuid[];\n  snapshots jsonb[] := ARRAY[]::jsonb[];\n  hashes text[] := ARRAY[]::text[];\n  statements text[] := ARRAY[]::text[];\n  topics text[] := ARRAY[]::text[];\n  sensitivities boolean[] := ARRAY[]::boolean[];\n  elsewheres boolean[] := ARRAY[]::boolean[];\n  batch uuid := gen_random_uuid();\n  batch_seq bigint;\n  batch_payload jsonb := '[]'::jsonb;\n  sensitive boolean;\n  elsewhere boolean;\n  seen integer := 0;\n  root_count integer := 0;\n  snapshot_bytes integer := 0;\n  result_bytes bigint := 0;\n  input_bytes bigint := 0;\n  proof_bytes bigint;\n  roots_examined bigint := 0;\n  n integer := 0;\n  i integer;\n  matches bigint;\n  admitted_at timestamptz;\nBEGIN\n  IF current_setting('transaction_isolation') <> 'read committed' THEN\n    RAISE EXCEPTION 'paused: traced knowledge recall requires READ COMMITTED isolation';\n  END IF;\n  -- Request bounds are operational refusal, never a truncated closure or completeness flag.\n  IF p_run IS NULL OR p_fence IS NULL OR p_fence <= 0\n     OR p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 100 THEN\n    RAISE EXCEPTION 'invalid: traced recall requires a run, positive fence and limit between 1 and 100';\n  END IF;\n  IF coalesce(cardinality(p_words),0) > 64\n     OR EXISTS (SELECT FROM unnest(p_words) w WHERE length(w)>256)\n     OR (SELECT coalesce(sum(length(w)),0) FROM unnest(p_words) w)>8192 THEN\n    RAISE EXCEPTION 'invalid: traced recall search exceeds its bounded request budget';\n  END IF;\n  -- Deliberately its OWN VOLATILE statement, before every current authority projection.\n  PERFORM gov._lock_workspace();\n  BEGIN\n    SELECT x.* INTO r FROM app.runs x WHERE x.workspace_id=sec.current_workspace()\n      AND x.id=p_run FOR UPDATE NOWAIT;\n  EXCEPTION WHEN lock_not_available THEN\n    RAISE EXCEPTION 'paused: the receiving run is changing; retry after its native owner settles';\n  END;\n  r := gov._holder(p_run,p_fence);\n  IF gov.run_standing(p_run) IS DISTINCT FROM 'ok' THEN\n    RAISE EXCEPTION 'paused: the receiving run no longer stands';\n  END IF;\n  ws := sec.current_workspace();\n  person := gov._run_person(p_run);\n  IF sec.current_run() IS DISTINCT FROM p_run OR sec.current_principal() IS DISTINCT FROM r.agent_id\n     OR person IS NULL OR NOT EXISTS (SELECT FROM app.principals p\n       WHERE p.workspace_id=ws AND p.id=person AND p.kind='person' AND p.status='active')\n     OR NOT sec.task_visible_to(r.task_id,person) THEN\n    RAISE EXCEPTION 'paused: the receiving run has no current native beneficiary audience';\n  END IF;\n  -- Do NOT lock knowledge/candidate rows here. retract_knowledge locks knowledge before head;\n  -- adding an inverse row lock would deadlock. These post-head MVCC reads see committed state;\n  -- a retraction waiting on our head linearizes after this recall.\n  FOR k IN SELECT x.* FROM app.knowledge x\n    WHERE x.workspace_id=ws AND x.status='accepted'\n    ORDER BY x.created_at,x.id LIMIT 5001\n  LOOP\n    seen := seen+1;\n    IF seen>5000 THEN\n      RAISE EXCEPTION 'paused: traced recall candidate scan exceeds its bounded budget';\n    END IF;\n    IF (k.valid_from IS NOT NULL AND k.valid_from>clock_timestamp())\n       OR (k.valid_to IS NOT NULL AND k.valid_to<=clock_timestamp())\n       OR (coalesce(cardinality(p_words),0)>0 AND NOT EXISTS (\n         SELECT FROM unnest(p_words) w WHERE position(lower(w) IN lower(k.statement))>0)) THEN\n      CONTINUE;\n    END IF;\n    SELECT * INTO c FROM app.knowledge_candidates x WHERE x.workspace_id=ws AND x.id=k.candidate_id;\n    -- Charge every candidate/input that will reach a helper, including UNKNOWN results.\n    -- No proof bytes or arbitrarily long citation arrays can hide behind output p_limit.\n    IF FOUND THEN\n      roots_examined := roots_examined+CASE WHEN jsonb_typeof(c.evidence)='array'\n        THEN jsonb_array_length(c.evidence) ELSE 1 END;\n      SELECT coalesce(octet_length(p.input_manifest::text),0) INTO proof_bytes\n        FROM app.knowledge_candidate_inputs p WHERE p.workspace_id=ws AND p.candidate_id=c.id;\n      input_bytes := input_bytes+octet_length(c.evidence::text)+octet_length(c.statement)\n        +octet_length(c.topic)+coalesce(proof_bytes,0);\n      IF roots_examined>1024 OR input_bytes>2097152 THEN\n        RAISE EXCEPTION 'paused: traced recall input derivation budget exceeded';\n      END IF;\n    END IF;\n    IF c.id IS NULL OR c.status IS DISTINCT FROM 'accepted' OR c.run_id IS NOT NULL\n       OR c.words_untrusted OR c.kept OR k.words_untrusted\n       OR c.terms_hash IS NULL OR k.statement IS DISTINCT FROM c.statement\n       OR k.topic IS DISTINCT FROM c.topic OR k.owner_id IS DISTINCT FROM c.owner_id\n       OR k.valid_from IS DISTINCT FROM c.valid_from OR k.valid_to IS DISTINCT FROM c.valid_to THEN\n      CONTINUE;\n    END IF;\n    closure := gov._knowledge_personal_closure_v1(c.id,person);\n    IF closure ->> 'state' IS DISTINCT FROM 'known_personal_closure' THEN\n      CONTINUE;\n    END IF;\n    SELECT count(*) INTO matches FROM app.ledger l WHERE l.workspace_id=ws\n      AND l.entry_type='knowledge.accepted' AND l.subject=k.id::text;\n    IF matches<>1 THEN CONTINUE; END IF;\n    SELECT * INTO accepted FROM app.ledger l WHERE l.workspace_id=ws\n      AND l.entry_type='knowledge.accepted' AND l.subject=k.id::text;\n    IF accepted.actor_id IS DISTINCT FROM k.accepted_by\n       OR accepted.payload IS DISTINCT FROM jsonb_build_object('candidate',c.id,'decision',k.decision_id,'owner',k.owner_id)\n       OR accepted.seq<=(closure #>> '{roots,proposal_seq}')::bigint\n       OR accepted.hash IS DISTINCT FROM sec.ledger_hash(accepted.prev_hash,ws,accepted.seq,\n         accepted.entry_type,accepted.actor_id,accepted.subject,accepted.payload,accepted.at)\n       OR NOT EXISTS (SELECT FROM app.ledger l WHERE l.workspace_id=ws\n         AND l.seq=accepted.seq-1 AND l.hash=accepted.prev_hash) THEN\n      CONTINUE;\n    END IF;\n    root_count := root_count+jsonb_array_length(closure #> '{roots,roots}');\n    IF root_count>1024 THEN\n      RAISE EXCEPTION 'paused: traced recall root snapshot exceeds its bounded write budget';\n    END IF;\n    SELECT coalesce(bool_or((root ->> 'currently_sensitive')::boolean),false),\n      coalesce(bool_or((root ->> 'currently_sensitive')::boolean AND (root ->> 'task_id')::uuid<>r.task_id),false)\n      INTO sensitive,elsewhere FROM jsonb_array_elements(closure #> '{roots,roots}') root;\n    snapshot := jsonb_build_object('format','knowledge-personal-closure-v1',\n      'knowledge_id',k.id,'candidate_id',c.id,'decision_id',k.decision_id,\n      'owner_id',k.owner_id,'valid_from',to_char(k.valid_from AT TIME ZONE 'UTC','YYYY-MM-DD\"T\"HH24:MI:SS.US\"Z\"'),\n      'valid_to',to_char(k.valid_to AT TIME ZONE 'UTC','YYYY-MM-DD\"T\"HH24:MI:SS.US\"Z\"'),\n      'words_untrusted',k.words_untrusted,'accepted_by',k.accepted_by,\n      'accepted_seq',accepted.seq::text,'accepted_hash',accepted.hash,'candidate_closure',closure);\n    snapshot_bytes := snapshot_bytes+octet_length(snapshot::text);\n    IF octet_length(snapshot::text)>131072 OR snapshot_bytes>2097152 THEN\n      RAISE EXCEPTION 'paused: traced recall snapshot byte budget exceeded';\n    END IF;\n    -- Legacy topic has no byte bound. Charge all returned text plus the canonical native\n    -- identity/cut fields before buffering; a large later row never yields a partial batch.\n    result_bytes := result_bytes+octet_length(k.statement)+octet_length(k.topic)+128;\n    IF result_bytes>2097152 THEN\n      RAISE EXCEPTION 'paused: traced recall result byte budget exceeded';\n    END IF;\n    n := n+1;\n    ids := array_append(ids,gen_random_uuid());\n    knowledge_ids := array_append(knowledge_ids,k.id);\n    candidate_ids := array_append(candidate_ids,c.id);\n    snapshots := array_append(snapshots,snapshot);\n    hashes := array_append(hashes,encode(sha256(convert_to(snapshot::text,'UTF8')),'hex'));\n    statements := array_append(statements,k.statement);\n    topics := array_append(topics,k.topic);\n    sensitivities := array_append(sensitivities,sensitive);\n    elsewheres := array_append(elsewheres,elsewhere);\n    batch_payload := batch_payload || jsonb_build_array(jsonb_build_object(\n      'read',ids[n],'knowledge',k.id,'candidate',c.id,'source',hashes[n]));\n    EXIT WHEN n=p_limit;\n  END LOOP;\n  -- Standing and validity are checked again after bounded projection work, before marking\n  -- or appending. No additional lease-expiry condition is invented; _holder/run_standing own it.\n  IF gov.run_standing(p_run) IS DISTINCT FROM 'ok' THEN\n    RAISE EXCEPTION 'paused: the receiving run stopped during traced recall';\n  END IF;\n  admitted_at := clock_timestamp();\n  IF EXISTS (SELECT FROM app.knowledge x WHERE x.workspace_id=ws AND x.id=ANY(knowledge_ids)\n    AND (x.status<>'accepted' OR (x.valid_from IS NOT NULL AND x.valid_from>admitted_at)\n      OR (x.valid_to IS NOT NULL AND x.valid_to<=admitted_at))) THEN\n    RAISE EXCEPTION 'paused: accepted knowledge changed or expired during traced recall';\n  END IF;\n  PERFORM gov._mark(p_run,NULL,\n    CASE WHEN true=ANY(sensitivities) THEN 'traced knowledge batch '||batch::text END,\n    CASE WHEN true=ANY(elsewheres) THEN 'traced knowledge batch '||batch::text END);\n  batch_seq := gov._append('knowledge.recalled',batch::text,\n    jsonb_build_object('version',1,'run',p_run,'fence',p_fence,'reads',batch_payload),r.agent_id);\n  -- A successful empty call records its invocation but certifies NO context completeness.\n  -- The only insertion loop precedes the ONLY result handover. Any failed insert raises and\n  -- rolls back marks, event, head and every row atomically; no catch/partial-success handler.\n  FOR i IN 1..n LOOP\n    INSERT INTO app.knowledge_reads(workspace_id,read_id,batch_id,batch_ordinal,read_seq,\n      receiving_run_id,receiving_fence,receiving_agent_id,receiving_person_id,receiving_task_id,\n      knowledge_id,candidate_id,source_snapshot,source_sha256,source_sensitive,source_elsewhere,read_at)\n    VALUES(ws,ids[i],batch,i,batch_seq,p_run,p_fence,r.agent_id,person,r.task_id,\n      knowledge_ids[i],candidate_ids[i],snapshots[i],hashes[i],sensitivities[i],elsewheres[i],admitted_at);\n  END LOOP;\n  RETURN QUERY SELECT ids[j],knowledge_ids[j],candidate_ids[j],batch_seq,statements[j],topics[j]\n    FROM generate_subscripts(ids,1) j ORDER BY j;\n  -- The client MUST hold these results privately until COMMIT returns command tag COMMIT.\nEND\n$$;\nALTER FUNCTION gov.recall_knowledge_traced_v1(uuid,bigint,text[],integer) OWNER TO backbone_gov;\nREVOKE ALL ON FUNCTION gov.recall_knowledge_traced_v1(uuid,bigint,text[],integer)\n  FROM PUBLIC,backbone_app,backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.recall_knowledge_traced_v1(uuid,bigint,text[],integer) TO backbone_app;\n\nSET ROLE backbone_owner;\n\n-- app/candidate_input_capture.sql\n\n-- Material closure foundation v1. Canonical versioned source; see its closed manifest.\nCREATE TRIGGER candidate_input_capture BEFORE INSERT ON app.knowledge_candidates\nFOR EACH ROW EXECUTE FUNCTION sec.t_candidate_input_capture_v1();\nALTER TABLE app.knowledge_candidates ENABLE ALWAYS TRIGGER candidate_input_capture;\n\n-- app/candidate_input_structure.sql\n\n-- Material closure foundation v1. Canonical versioned source; see its closed manifest.\nCREATE CONSTRAINT TRIGGER candidate_input_structure\nAFTER INSERT ON app.knowledge_candidates\nDEFERRABLE INITIALLY DEFERRED\nFOR EACH ROW EXECUTE FUNCTION sec.t_candidate_input_structure();\nALTER TABLE app.knowledge_candidates ENABLE ALWAYS TRIGGER candidate_input_structure;\n\nRESET ROLE;\n"} as const);
